test("getRunHealth accepts strict 0.35 orphan, cancel-pending, quota, and operation metadata shapes", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);
  const env = fakeSmithersEnv(project);
  const run = await startRun({ projectRoot: project, runId: "smithers-034-shapes", env });
  assert.equal(run.ok, true, JSON.stringify(run.diagnostics));
  const envelope = currentStatusEnvelope("ultrafuzz-smithers-034-shapes");
  const base = envelope.data as Record<string, unknown>;

  for (const verdict of ["orphaned", "cancel-pending"] as const) {
    setFakeSmithersStatus(project, {
      ...envelope,
      data: {
        ...base,
        verdict,
        // The orphaned reason is the pinned runner's own wording, remediation included. The run ID
        // contains "smithers" so the recommended command is shown to keep a chosen ID intact.
        reason:
          verdict === "orphaned"
            ? "engine heartbeat is stale and its process is gone (last heartbeat 2026-08-13T00:00:00.000Z); the run is orphaned — resume it with `smithers supervise -r ultrafuzz-smithers-034-shapes`"
            : `run is ${verdict}`,
        liveness: {
          state: verdict,
          unhealthy: { kind: "engine-heartbeat-stale", lastHeartbeatAt: "2026-08-13T00:00:00.000Z" }
        },
        startedBy: { harness: "codex", sessionId: "session-1", detected: true },
        attention: {
          operation: "time travel",
          opId: null,
          crossedCount: 2,
          blockingCount: 1,
          revertibleCount: 1,
          warningCount: 0,
          lateCompletion: false,
          archivedByOp: null,
          timestampMs: 2_000
        },
        information: { operation: "rewind", warningCount: 1, timestampMs: 2_001 },
        oneshotControl: { kind: "steer", status: "agent-acked", messageId: "message-1", timestampMs: 2_002 }
      }
    });
    const health = await getRunHealth({ projectRoot: project, runId: "smithers-034-shapes", env });
    assert.equal(health.ok, true, `${verdict}: ${JSON.stringify(health.diagnostics)}`);
    assert.equal(health.value?.verdict, verdict);
    if (verdict === "orphaned") {
      // `workflow runner supervise -r ...` is not a command an operator can run; resume is.
      assert.match(
        health.value?.reason ?? "",
        /the run is orphaned — resume it with `ultrafuzz resume smithers-034-shapes`$/u
      );
    }
    assert.equal(health.value?.started_by?.session_id, "session-1");
    assert.equal(health.value?.attention?.crossed_count, 2);
    assert.equal(health.value?.oneshot_control?.message_id, "message-1");
  }

  // The pinned runner's paused reason, which names its own resume command.
  setFakeSmithersStatus(project, {
    ...envelope,
    data: {
      ...base,
      status: "paused",
      verdict: "paused",
      reason: "run was gracefully paused; resume with `smithers up --resume <runId>`",
      liveness: { state: "paused" }
    }
  });
  const paused = await getRunHealth({ projectRoot: project, runId: "smithers-034-shapes", env });
  assert.equal(paused.ok, true, JSON.stringify(paused.diagnostics));
  assert.equal(paused.value?.reason, "run was gracefully paused; resume with `ultrafuzz resume smithers-034-shapes`");

  setFakeSmithersStatus(project, {
    ...envelope,
    data: {
      ...base,
      status: "waiting-quota",
      verdict: "waiting-quota",
      reason: "5 tasks quota-parked",
      bottleneck: [
        { nodeId: "node-a", iteration: 0, state: "quota-parked", detail: null },
        { nodeId: "node-b", iteration: 0, state: "quota-parked", detail: null },
        { nodeId: "node-c", iteration: 0, state: "quota-parked", detail: null }
      ],
      bottleneckOmitted: 2,
      quota: { parkedCount: 5, parkedNodeIds: ["node-a", "node-b", "node-c"], resetAtMs: null },
      liveness: { state: "waiting-quota" }
    }
  });
  const quota = await getRunHealth({ projectRoot: project, runId: "smithers-034-shapes", env });
  assert.equal(quota.ok, true, JSON.stringify(quota.diagnostics));
  assert.equal(quota.value?.quota?.parked_count, 5);
  assert.equal(quota.value?.gating[0]?.state, "quota-parked");
});

// The `status` surface, end to end over the shapes Smithers 0.35.0 actually
// emits. `counts.stalled` is unconditional there, and `degraded` is now the
// ordinary verdict for a run that tolerated a `continueOnFail` child -- both of
// which the 0.34.0-shaped fixtures could never have produced.
test("getRunHealth accepts the pinned 0.35.0 status counts and folds stalled nodes into failed", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);
  const env = fakeSmithersEnv(project);
  const run = await startRun({ projectRoot: project, runId: "stalled-health-run", env });
  assert.equal(run.ok, true, JSON.stringify(run.diagnostics));
  const envelope = currentStatusEnvelope("ultrafuzz-stalled-health-run");
  const base = envelope.data as Record<string, unknown>;
  const counts = base.counts as Record<string, number>;

  setFakeSmithersStatus(project, {
    ...envelope,
    data: {
      ...base,
      status: "finished",
      // 0.35.0's second `degraded` branch: `failedChildren > 0` on a finished
      // run, which for Ultrafuzz is an ordinary tolerated `continueOnFail` lane.
      verdict: "degraded",
      reason: "run finished with 2 tolerated failed children",
      counts: { ...counts, finished: 2, inProgress: 0, pending: 0, failed: 1, stalled: 2, total: 6, other: 1 },
      liveness: { state: "succeeded-with-failures" },
      finishedAtMs: 2_000
    }
  });

  const health = await getRunHealth({ projectRoot: project, runId: "stalled-health-run", env });
  assert.equal(health.ok, true, JSON.stringify(health.diagnostics));
  assert.equal(health.value?.verdict, "degraded");
  // Ultrafuzz has no `stalled` node status, so the runner's stalled bucket joins
  // the failed one rather than disappearing or becoming an eleventh count.
  assert.equal(health.value?.counts.failed, 3);
  assert.deepEqual(sortedKeys(Object.keys(health.value?.counts ?? {})), [
    "failed",
    "finished",
    "in_progress",
    "other",
    "pending",
    "skipped",
    "total",
    "waiting_approval",
    "waiting_event",
    "waiting_timer"
  ]);

  // A document without the bucket is a 0.34.0 document; the parser is exact-key
  // in both directions, so it must be refused rather than defaulted to zero.
  const { stalled: _dropped, ...withoutStalled } = counts;
  setFakeSmithersStatus(project, { ...envelope, data: { ...base, counts: withoutStalled } });
  const superseded = await getRunHealth({ projectRoot: project, runId: "stalled-health-run", env });
  assert.equal(superseded.ok, false);
  assert.deepEqual(
    superseded.diagnostics.map((diagnostic) => diagnostic.code),
    ["WORKFLOW_STATUS_INVALID"]
  );
});

