test("OpenRouter stdout compatibility preserves record order for every pipe split", async () => {
  const { SMITHERS_COMPATIBILITY_PATCHES } = await import("../src/smithers.js");
  const patch = SMITHERS_COMPATIBILITY_PATCHES.find((candidate) => candidate.id === "agents_ordered_stdout");
  assert.ok(patch);
  const sourceRoot = pinnedRunnerSourceDir("@smthrs/agents", "BaseCliAgent/BaseCliAgent");
  const { createAgentStdoutTextEmitter } = (await import(
    pathToFileURL(path.join(sourceRoot, "BaseCliAgent", "index.js")).href
  )) as {
    createAgentStdoutTextEmitter(options: { outputFormat: string; onText(text: string): void }): {
      push(chunk: string): void;
      flush(finalText?: string): void;
    };
  };
  const { CodexAgent } = (await import(pathToFileURL(path.join(sourceRoot, "CodexAgent.js")).href)) as {
    CodexAgent: new () => {
      createOutputInterpreter(): { onStdoutLine(line: string): Array<{ type: string; ok?: boolean }> };
    };
  };
  const dispatchFactory = async (snippet: string) => {
    const module = (await import(
      `data:text/javascript,${encodeURIComponent(
        `export function dispatch(commandSpec, stdoutEmitter, handleInterpreterChunk) { return ({${snippet}}).onStdout; }`
      )}`
    )) as {
      dispatch(
        command: { orderedStdoutRecords?: boolean },
        emitter: { push(chunk: string): void },
        interpret: (stream: string, chunk: string) => void
      ): (chunk: string) => void;
    };
    return module.dispatch;
  };
  const patched = await dispatchFactory(patch.patched);
  const upstream = await dispatchFactory(patch.patchable);
  const transcript = [
    { type: "message", role: "assistant", content: "prefix" },
    { type: "error", message: "HTTP 429 Too Many Requests" },
    { type: "message", role: "assistant", content: "trailing" }
  ]
    .map((record) => JSON.stringify(record))
    .join("\n");
  const observe = (dispatch: typeof patched, enabled: boolean, chunks: string[]) => {
    const observed: string[] = [];
    const emitter = createAgentStdoutTextEmitter({
      outputFormat: "stream-json",
      onText: (text) => observed.push(text)
    });
    const interpreter = new CodexAgent().createOutputInterpreter();
    let pending = "";
    const interpret = (line: string) => {
      for (const event of interpreter.onStdoutLine(line)) {
        if (event.type === "completed" && event.ok === false) observed.push("terminal");
      }
    };
    const accept = dispatch({ orderedStdoutRecords: enabled }, emitter, (_stream, chunk) => {
      pending += chunk;
      const lines = pending.split("\n");
      pending = lines.pop() ?? "";
      for (const line of lines) interpret(line);
    });
    for (const chunk of chunks) accept(chunk);
    interpret(pending);
    emitter.flush("fallback");
    return observed;
  };
  const expected = ["prefix", "terminal", "trailing"];
  for (const suffix of ["", "\n"]) {
    const complete = transcript + suffix;
    assert.deepEqual(observe(patched, true, [complete]), expected);
    for (let split = 0; split <= complete.length; split += 1) {
      assert.deepEqual(observe(patched, true, [complete.slice(0, split), complete.slice(split)]), expected);
    }
    assert.deepEqual(observe(patched, true, [...complete]), expected);
    assert.deepEqual(observe(patched, false, [complete]), observe(upstream, false, [complete]));
  }
  assert.deepEqual(observe(upstream, true, [transcript + "\n"]), ["prefix", "trailing", "terminal"]);
});

test("compatibility patcher rewrites every described workaround", async () => {
  const { applySmithersCompatibilityPatches, inspectSmithersInstallation, SMITHERS_COMPATIBILITY_PATCHES } =
    await import("../src/smithers.js");
  const project = tempProject();
  writeFakeInstalledSmithers(project);
  const nodeModules = path.join(project, ".smithers", "node_modules");
  const runnerRoot = path.join(nodeModules, "smthrs");
  const installedRunner = createRequire(import.meta.url).resolve("smthrs/bin/smithers");
  assert.ok(SMITHERS_COMPATIBILITY_PATCHES.length > 0, "no compatibility patches were described");
  // Seeded from the descriptions themselves, so a newly described workaround is
  // covered here without a second edit and cannot land reported-but-never-applied.
  const sources = SMITHERS_COMPATIBILITY_PATCHES.map((patch) => ({
    patch,
    source: path.join(nodeModules, ...patch.packageName.split("/"), ...patch.sourceRelativePath.split("/"))
  }));
  // Grouped by file: two workarounds can target the same source, and writing per
  // descriptor would let the second write clobber the first anchor.
  const bySource = new Map<string, string[]>();
  for (const { patch, source } of sources) {
    bySource.set(source, [...(bySource.get(source) ?? []), patch.patchable]);
  }
  for (const { patch, source } of sources) {
    const packageRoot = path.join(nodeModules, ...patch.packageName.split("/"));
    fs.mkdirSync(path.dirname(source), { recursive: true });
    fs.writeFileSync(
      path.join(packageRoot, "package.json"),
      `${JSON.stringify({ name: patch.packageName, version: SMITHERS_VERSION })}\n`,
      "utf8"
    );
  }
  // These anchors are intentionally verified but not rewritten. A fabricated
  // compatibility tree must carry them so the fixture exercises the same
  // preconditions as the pinned installation.
  const { SMITHERS_REQUIRED_ENGINE_ANCHORS } = await import("../src/smithers.js");
  for (const required of SMITHERS_REQUIRED_ENGINE_ANCHORS) {
    const source = path.join(
      nodeModules,
      ...required.packageName.split("/"),
      ...required.sourceRelativePath.split("/")
    );
    bySource.set(source, [...(bySource.get(source) ?? []), required.anchor]);
  }
  for (const [source, anchors] of bySource) {
    fs.mkdirSync(path.dirname(source), { recursive: true });
    if (source.endsWith(SMITHERS_BIN_PATH)) {
      fs.cpSync(path.dirname(installedRunner), path.dirname(source), { recursive: true });
      fs.writeFileSync(source, await pristineSmithersSource("smthrs", installedRunner), "utf8");
      continue;
    }
    fs.writeFileSync(source, `${anchors.join("\n")}\n`, "utf8");
  }

  {
    // Bun's startup controls are addressed relative to the inherited descriptor
    // root instead of a /proc literal, so the same patch works where /proc is
    // absent. The resume patch is a separate module and must not depend on the
    // helper declared in the CLI entry module.
    const resumeStartup = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "resume_snapshot_transfer");
    assert.ok(resumeStartup);
    assert.doesNotMatch(resumeStartup.patched, /ultrafuzzBunStartupArgsFor/u);
    assert.match(
      resumeStartup.patched,
      /"--config=" \+ snapshotChildRoot.*"--env-file=" \+ snapshotChildRoot.*"--preload=" \+ snapshotChildRoot/su
    );
    const startupAnchor = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "process_snapshot_anchor");
    assert.ok(startupAnchor);
    assert.match(startupAnchor.patched, /ultrafuzzBunStartupArgsFor/u);
    assert.match(
      startupAnchor.patched,
      /"--env-file=" \+ root \+ "\/controls\/bun-empty\.env".*"--no-addons".*"--preload=" \+ root \+ "\/controls\/bun-module-confinement\.js"/u
    );
    // The Linux spelling of that root is unchanged; only darwin resolves elsewhere.
    assert.match(startupAnchor.patched, /: "\/proc\/self\/fd\/3";/u);
    assert.match(
      startupAnchor.patched,
      /process\.platform !== "darwin"\) return realpathSync\(left\) === realpathSync\(right\)/u
    );
    assert.match(startupAnchor.patched, /a\.isFile\(\) && b\.isFile\(\) && a\.dev === b\.dev && a\.ino === b\.ino/u);
    for (const id of [
      "workflow_path_persistence",
      "process_snapshot_anchor",
      "replay_workflow_path",
      "fork_workflow_path",
      "engine_workflow_path"
    ] as const) {
      const identity = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === id);
      assert.ok(identity);
      assert.match(identity.patched, /ultrafuzzSameWorkflowFile/u, `${id} bypasses verified workflow identity`);
    }
    const engineIdentityImport = SMITHERS_COMPATIBILITY_PATCHES.find(
      (patch) => patch.id === "engine_workflow_path_import"
    );
    assert.ok(engineIdentityImport);
    assert.match(engineIdentityImport.patched, /rmSync, statSync, writeFileSync/u);
    const relaunch = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "manifest_relaunch");
    assert.ok(relaunch);
    assert.match(relaunch.patched, /relaunchSnapshotTransfer.*ultrafuzzBunStartupArgs.*descriptor/su);
    const lifecycle = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "lifecycle_trace_summary");
    assert.ok(lifecycle);
    const patchableTypes = new Set([...lifecycle.patchable.matchAll(/"([A-Za-z]+)"/gu)].map((match) => match[1]!));
    const patchedTypes = [...lifecycle.patched.matchAll(/"([A-Za-z]+)"/gu)].map((match) => match[1]!);
    assert.deepEqual(
      patchedTypes.filter((type) => !patchableTypes.has(type)),
      ["AgentTraceSummary"],
      "the observability compatibility patch must expose only the bounded trace summary event"
    );
    const upstreamRunner = sources.find(({ patch }) => patch.id === "local_delegation");
    assert.ok(upstreamRunner);
    assert.throws(
      () => bindSmithersExecutableCapability({}, upstreamRunner.source),
      /delegate controller authority to target code/u
    );
  }
  applySmithersCompatibilityPatches(project);
  const patchedRunner = sources.find(({ patch }) => patch.id === "local_delegation");
  assert.ok(patchedRunner);
  assert.equal(fs.statSync(patchedRunner.source).mode & 0o777, 0o500);
  for (const { patch, source } of sources) {
    // `patched` is the whole replacement text, so its presence is exactly the
    // statement "this workaround landed in the installed source".
    assert.equal(
      fs.readFileSync(source, "utf8").includes(patch.patched),
      true,
      `${patch.id} is described but was never applied to ${source}`
    );
  }
  {
    const resumeTransfer = sources.find(({ patch }) => patch.id === "resume_snapshot_transfer");
    assert.ok(resumeTransfer);
    const [predecessor] = resumeTransfer.patch.predecessors ?? [];
    assert.ok(predecessor);
    assert.notEqual(predecessor, resumeTransfer.patch.patched);
    const current = fs.readFileSync(resumeTransfer.source, "utf8");
    assert.equal(current.split(resumeTransfer.patch.patched).length, 2);
    fs.writeFileSync(resumeTransfer.source, current.replace(resumeTransfer.patch.patched, predecessor), "utf8");
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.resume_snapshot_transfer, "missing");
    applySmithersCompatibilityPatches(project);
    assert.equal(fs.readFileSync(resumeTransfer.source, "utf8").includes(resumeTransfer.patch.patched), true);
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.resume_snapshot_transfer, "applied");

    const unscopedHelperPredecessor = resumeTransfer.patch.predecessors?.find((candidate) =>
      candidate.includes("ultrafuzzBunStartupArgsFor(snapshotChildRoot)")
    );
    assert.ok(unscopedHelperPredecessor);
    fs.writeFileSync(
      resumeTransfer.source,
      current.replace(resumeTransfer.patch.patched, unscopedHelperPredecessor),
      "utf8"
    );
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.resume_snapshot_transfer, "missing");
    applySmithersCompatibilityPatches(project);
    const migratedUnscopedHelper = fs.readFileSync(resumeTransfer.source, "utf8");
    assert.equal(migratedUnscopedHelper.includes("ultrafuzzBunStartupArgsFor(snapshotChildRoot)"), false);
    assert.equal(migratedUnscopedHelper.includes(resumeTransfer.patch.patched), true);
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.resume_snapshot_transfer, "applied");

    fs.writeFileSync(resumeTransfer.source, `${predecessor}\n${predecessor}\n`, "utf8");
    assert.equal(
      inspectSmithersInstallation(runnerRoot).compatibility_patches.resume_snapshot_transfer,
      "incompatible"
    );
    assert.throws(
      () => applySmithersCompatibilityPatches(project),
      /detached resume execution snapshot transfer implementation is incompatible/u
    );

    fs.writeFileSync(
      resumeTransfer.source,
      `${resumeTransfer.patch.patched}\n${resumeTransfer.patch.patchable}\n`,
      "utf8"
    );
    assert.equal(
      inspectSmithersInstallation(runnerRoot).compatibility_patches.resume_snapshot_transfer,
      "incompatible"
    );
    assert.throws(
      () => applySmithersCompatibilityPatches(project),
      /detached resume execution snapshot transfer implementation is incompatible/u
    );
    fs.writeFileSync(resumeTransfer.source, current, "utf8");
  }
  {
    const processAnchor = sources.find(({ patch }) => patch.id === "process_snapshot_anchor");
    assert.ok(processAnchor);
    const [predecessor, nested, reusedInheritedDescriptor] = processAnchor.patch.predecessors ?? [];
    assert.ok(predecessor);
    assert.ok(nested);
    assert.ok(reusedInheritedDescriptor);
    assert.equal(processAnchor.patch.predecessors?.length, 3);
    const current = fs.readFileSync(processAnchor.source, "utf8");
    assert.equal(current.split(processAnchor.patch.patched).length, 2);

    fs.writeFileSync(processAnchor.source, current.replace(processAnchor.patch.patched, predecessor), "utf8");
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.process_snapshot_anchor, "missing");
    applySmithersCompatibilityPatches(project);
    const migratedPredecessor = fs.readFileSync(processAnchor.source, "utf8");
    assert.equal(migratedPredecessor.split(processAnchor.patch.patched).length, 2);
    assert.equal(migratedPredecessor.includes(nested), false);
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.process_snapshot_anchor, "applied");

    fs.writeFileSync(
      processAnchor.source,
      current.replace(processAnchor.patch.patched, reusedInheritedDescriptor),
      "utf8"
    );
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.process_snapshot_anchor, "missing");
    applySmithersCompatibilityPatches(project);
    const migratedReusedInheritedDescriptor = fs.readFileSync(processAnchor.source, "utf8");
    assert.equal(migratedReusedInheritedDescriptor.split(processAnchor.patch.patched).length, 2);
    assert.equal(migratedReusedInheritedDescriptor.includes(reusedInheritedDescriptor), false);
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.process_snapshot_anchor, "applied");

    fs.writeFileSync(processAnchor.source, current.replace(processAnchor.patch.patched, nested), "utf8");
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.process_snapshot_anchor, "missing");
    applySmithersCompatibilityPatches(project);
    const migratedNested = fs.readFileSync(processAnchor.source, "utf8");
    assert.equal(migratedNested.split(processAnchor.patch.patched).length, 2);
    assert.equal(migratedNested.includes(nested), false);
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.process_snapshot_anchor, "applied");

    const mutatedNested = nested.replace('"--preserve-symlinks"', '"--mutated-outer-startup-flag"');
    assert.notEqual(mutatedNested, nested);
    fs.writeFileSync(processAnchor.source, current.replace(processAnchor.patch.patched, mutatedNested), "utf8");
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.process_snapshot_anchor, "incompatible");
    assert.throws(
      () => applySmithersCompatibilityPatches(project),
      /process-owned execution snapshot implementation is incompatible/u
    );

    const unknownPredecessor = predecessor.replace('"--preserve-symlinks"', '"--unregistered-startup-flag"');
    assert.notEqual(unknownPredecessor, predecessor);
    fs.writeFileSync(processAnchor.source, current.replace(processAnchor.patch.patched, unknownPredecessor), "utf8");
    assert.equal(inspectSmithersInstallation(runnerRoot).compatibility_patches.process_snapshot_anchor, "incompatible");
    assert.throws(
      () => applySmithersCompatibilityPatches(project),
      /process-owned execution snapshot implementation is incompatible/u
    );
    fs.writeFileSync(processAnchor.source, current, "utf8");
  }
  {
    const delegation = sources.find(({ patch }) => patch.id === "local_delegation");
    assert.ok(delegation);
    const target = path.join(project, "hostile-target"),
      targetRunner = path.join(target, ".smithers", "node_modules", "smthrs", ...SMITHERS_BIN_PATH.split("/")),
      trustedMarker = path.join(project, "operator-cli-ran"),
      hostileMarker = path.join(project, "target-cli-ran"),
      cliRoot = path.join(nodeModules, "@smthrs", "cli");
    fs.mkdirSync(path.dirname(targetRunner), { recursive: true });
    fs.writeFileSync(
      path.join(cliRoot, "package.json"),
      // Mirrors the real package's subpath export map, not just its main entry:
      // the pinned runner's `bin/smithers.js` imports
      // `@smthrs/cli/node-loader/registerNodeWorkflowLoader` before the CLI
      // itself, so a fixture that publishes only `.` cannot even be executed.
      `${JSON.stringify({
        name: "@smthrs/cli",
        version: SMITHERS_VERSION,
        type: "module",
        exports: { ".": "./index.js", "./*": "./*.js" }
      })}\n`,
      "utf8"
    );
    fs.mkdirSync(path.join(cliRoot, "node-loader"), { recursive: true });
    // Faithful to the real hook: under Bun it installs nothing and returns
    // false, because Bun already transpiles TypeScript and JSX on import.
    fs.writeFileSync(
      path.join(cliRoot, "node-loader", "registerNodeWorkflowLoader.js"),
      'export function registerNodeWorkflowLoader() {\n  return typeof Bun === "undefined";\n}\n',
      "utf8"
    );
    fs.writeFileSync(
      path.join(cliRoot, "index.js"),
      `await Bun.write(process.env.ULTRAFUZZ_TRUSTED_MARKER, "trusted");\n`,
      "utf8"
    );
    fs.writeFileSync(
      path.join(target, ".smithers", "node_modules", "smthrs", "package.json"),
      `${JSON.stringify({ name: "smthrs", version: SMITHERS_VERSION, type: "module", bin: { smithers: SMITHERS_BIN_PATH } })}\n`,
      "utf8"
    );
    fs.writeFileSync(targetRunner, `await Bun.write(process.env.ULTRAFUZZ_HOSTILE_MARKER, "hostile");\n`, "utf8");
    execFileSync(
      "bun",
      [
        `--config=${process.platform === "win32" ? "NUL" : "/dev/null"}`,
        "--no-env-file",
        "--no-install",
        delegation.source,
        "inspect"
      ],
      {
        cwd: target,
        env: { ...process.env, ULTRAFUZZ_TRUSTED_MARKER: trustedMarker, ULTRAFUZZ_HOSTILE_MARKER: hostileMarker }
      }
    );
    assert.equal(fs.existsSync(trustedMarker), true);
    assert.equal(fs.existsSync(hostileMarker), false);
  }
});

test("compatibility patches declare every ultrafuzz helper inside the module they patch", async () => {
  const { SMITHERS_COMPATIBILITY_PATCHES } = await import("../src/smithers.js");
  // Patches land in separate ES modules, so a helper one module's patch declares
  // is out of scope for another module's patch even though both are always
  // applied together: resume-detached.js once called helpers that only the
  // src/index.js anchor declared and threw ReferenceError at resume time.
  const patchedByModule = new Map<string, string>();
  for (const patch of SMITHERS_COMPATIBILITY_PATCHES) {
    const module = `${patch.packageName}/${patch.sourceRelativePath}`;
    patchedByModule.set(module, `${patchedByModule.get(module) ?? ""}\n${patch.patched}`);
  }
  assert.ok(patchedByModule.has("@smthrs/cli/src/resume-detached.js"));
  for (const [module, patched] of patchedByModule) {
    const declared = new Set(
      [...patched.matchAll(/(?<=\b(?:const|let|var|function|class)\s+)ultrafuzz[A-Za-z0-9_]+\b/gu)].map(
        (match) => match[0]
      )
    );
    const undeclared = [...patched.matchAll(/\bultrafuzz[A-Za-z0-9_]+\b/gu)]
      .filter(
        // An object-literal key names a field on the value it travels with, not a
        // binding in the module, so it is the one non-reference form allowed here.
        (match) =>
          !(
            /[{,]\s*$/u.test(patched.slice(0, match.index)) &&
            /^\s*:(?!:)/u.test(patched.slice(match.index + match[0].length))
          )
      )
      .map((match) => match[0])
      .filter((name) => !declared.has(name));
    assert.deepEqual([...new Set(undeclared)], [], `${module} uses ultrafuzz helpers its patched text never declares`);
  }
});

type OwnedUsageRow = {
  inputTokens?: number;
  freshInputTokens?: number | null;
  outputTokens?: number;
  cacheReadTokens?: number;
  cacheWriteTokens?: number;
  reasoningTokens?: number;
  costUsd?: number | null;
  updatedAtMs: number;
  runtimeOwnerId?: string | null;
  attempt?: number;
};

type OwnedUsageTotal = {
  inputTokens: number;
  freshInputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
  reasoningTokens: number;
  costUsd: number | null;
  attempts: number;
};

type OwnedUsageAdapter = {
  recordRunTokenUsageOwned: (row: Record<string, unknown>) => PromiseLike<boolean>;
  getRunTokenUsage: (runId: string) => PromiseLike<OwnedUsageTotal>;
};

type OwnedUsageFixture = {
  adapter: OwnedUsageAdapter;
  sqlite: BunSqliteHandle;
  persist: (row: OwnedUsageRow) => PromiseLike<boolean>;
  tokenEvents: () => Array<{ timestamp_ms: number; payload_json: string }>;
  usageRowsForAttempt: (attempt: number) => number;
  close: () => void;
};

function persistOwnedUsage(adapter: OwnedUsageAdapter, row: OwnedUsageRow): PromiseLike<boolean> {
  const resolved = {
    runId: "run-owned-usage",
    nodeId: "node:usage",
    iteration: 0,
    attempt: row.attempt ?? 1,
    runtimeOwnerId: row.runtimeOwnerId ?? "owner-a",
    model: "provider/model",
    agent: "PiAgent",
    ...row
  };
  const event = {
    type: "TokenUsageReported",
    runId: resolved.runId,
    nodeId: resolved.nodeId,
    iteration: resolved.iteration,
    attempt: resolved.attempt,
    model: resolved.model,
    agent: resolved.agent,
    inputTokens: resolved.inputTokens ?? 0,
    ...(resolved.freshInputTokens == null ? {} : { freshInputTokens: resolved.freshInputTokens }),
    outputTokens: resolved.outputTokens ?? 0,
    ...(resolved.cacheReadTokens === undefined ? {} : { cacheReadTokens: resolved.cacheReadTokens }),
    ...(resolved.cacheWriteTokens === undefined ? {} : { cacheWriteTokens: resolved.cacheWriteTokens }),
    ...(resolved.reasoningTokens === undefined ? {} : { reasoningTokens: resolved.reasoningTokens }),
    ...(resolved.costUsd == null ? {} : { costUsd: resolved.costUsd }),
    timestampMs: resolved.updatedAtMs
  };
  return adapter.recordRunTokenUsageOwned({ ...resolved, event });
}

async function openOwnedUsageFixture(): Promise<OwnedUsageFixture> {
  const { SMITHERS_COMPATIBILITY_PATCHES } = await import("../src/smithers.js");
  const ownedUsagePatch = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "owned_usage");
  assert.ok(ownedUsagePatch);
  const pinnedDbSource = pinnedRunnerSourceDir("@smthrs/db", "adapter");
  const pinnedDbRoot = path.dirname(pinnedDbSource);
  const isolatedDbRoot = path.join(tempProject(), "node_modules", "@smthrs", "db");
  fs.mkdirSync(path.dirname(isolatedDbRoot), { recursive: true });
  fs.cpSync(pinnedDbRoot, isolatedDbRoot, { recursive: true });
  fs.rmSync(path.join(isolatedDbRoot, "node_modules"), { recursive: true, force: true });
  fs.symlinkSync(path.dirname(path.dirname(pinnedDbRoot)), path.join(isolatedDbRoot, "node_modules"), "dir");
  const adapterSource = path.join(isolatedDbRoot, "src", "adapter.js");
  const stockAdapter = fs.readFileSync(adapterSource, "utf8");
  assert.equal(stockAdapter.split(ownedUsagePatch.patchable).length, 2);
  fs.writeFileSync(adapterSource, stockAdapter.replace(ownedUsagePatch.patchable, ownedUsagePatch.patched), "utf8");
  const { openDurableSqliteDatabase } = (await import(
    pathToFileURL(path.join(isolatedDbRoot, "src", "openDurableSqliteDatabase.js")).href
  )) as { openDurableSqliteDatabase: (file: string) => { db: unknown; close: () => void } };
  const { ensureSqlMessageStorage } = (await import(
    pathToFileURL(path.join(isolatedDbRoot, "src", "sql-message-storage.js")).href
  )) as { ensureSqlMessageStorage: (db: unknown) => Promise<void> };
  const { SmithersDb } = (await import(pathToFileURL(adapterSource).href)) as {
    SmithersDb: new (db: unknown) => OwnedUsageAdapter;
  };
  const handle = openDurableSqliteDatabase(path.join(tempProject(), "owned-usage.db"));
  await ensureSqlMessageStorage(handle.db);
  const sqlite = (handle.db as { $client: BunSqliteHandle }).$client;
  sqlite
    .query(
      `INSERT INTO _smithers_runs
       (run_id, workflow_name, status, created_at_ms, runtime_owner_id)
       VALUES (?, ?, ?, ?, ?)`
    )
    .run("run-owned-usage", "workflow", "running", 1, "owner-a");
  for (const attempt of [1, 2]) {
    sqlite
      .query(
        `INSERT INTO _smithers_attempts
         (run_id, node_id, iteration, attempt, state, started_at_ms)
         VALUES (?, ?, ?, ?, ?, ?)`
      )
      .run("run-owned-usage", "node:usage", 0, attempt, "in-progress", attempt);
  }
  const adapter = new SmithersDb(handle.db);
  return {
    adapter,
    sqlite,
    persist: (row) => persistOwnedUsage(adapter, row),
    tokenEvents: () =>
      sqlite
        .query(
          `SELECT timestamp_ms, payload_json FROM _smithers_events
           WHERE run_id = ? AND type = 'TokenUsageReported' ORDER BY seq ASC`
        )
        .all(["run-owned-usage"]) as Array<{ timestamp_ms: number; payload_json: string }>,
    usageRowsForAttempt: (attempt) =>
      Number(
        sqlite
          .query(
            `SELECT COUNT(*) AS count FROM _smithers_run_usage
             WHERE run_id = ? AND node_id = ? AND iteration = ? AND attempt = ?`
          )
          .get("run-owned-usage", "node:usage", 0, attempt)?.count ?? 0
      ),
    close: handle.close
  };
}

async function assertOwnedUsageMonotonicity(fixture: OwnedUsageFixture): Promise<void> {
  const { persist, sqlite, tokenEvents } = fixture;
  const initial: OwnedUsageRow = {
    inputTokens: 10,
    freshInputTokens: null,
    outputTokens: 5,
    cacheReadTokens: 6,
    cacheWriteTokens: 0,
    reasoningTokens: 2,
    costUsd: 0.5,
    updatedAtMs: 10
  };
  assert.equal(await persist(initial), true);
  const initialEvent = tokenEvents()[0];
  assert.ok(initialEvent);
  assert.equal(JSON.parse(initialEvent.payload_json).inputTokens, 10);
  // Equal terminal telemetry is accepted and atomically includes its event.
  assert.equal(await persist({ ...initial, updatedAtMs: 11 }), true);
  assert.equal(tokenEvents().length, 2);
  assert.equal(await persist({ ...initial, inputTokens: 9, updatedAtMs: 12 }), false);
  const upgraded = { ...initial, inputTokens: 11, freshInputTokens: 5, updatedAtMs: 13 };
  assert.equal(await persist(upgraded), true);
  assert.equal(await persist({ ...upgraded, inputTokens: 12, freshInputTokens: null, updatedAtMs: 14 }), true);
  const unknownFreshEvent = tokenEvents().at(-1);
  assert.ok(unknownFreshEvent);
  const unknownFreshPayload = JSON.parse(unknownFreshEvent.payload_json) as Record<string, unknown>;
  assert.equal(unknownFreshPayload.inputTokens, 12);
  assert.equal("freshInputTokens" in unknownFreshPayload, false);
  assert.equal(
    await persist({
      ...upgraded,
      inputTokens: 12,
      outputTokens: 6,
      cacheReadTokens: undefined,
      reasoningTokens: undefined,
      costUsd: null,
      updatedAtMs: 15
    }),
    true
  );
  const lastEvent = tokenEvents().at(-1);
  assert.ok(lastEvent);
  const incompleteEvent = JSON.parse(lastEvent.payload_json) as Record<string, unknown>;
  assert.equal(incompleteEvent.inputTokens, 12);
  assert.equal("cacheReadTokens" in incompleteEvent, false);
  assert.equal("reasoningTokens" in incompleteEvent, false);
  assert.equal("costUsd" in incompleteEvent, false);
  assert.equal(
    await persist({
      inputTokens: 20,
      freshInputTokens: 8,
      outputTokens: 7,
      cacheReadTokens: 9,
      cacheWriteTokens: 1,
      reasoningTokens: 3,
      costUsd: 0.75,
      updatedAtMs: 16
    }),
    true
  );
  assert.equal(await persist({ ...upgraded, runtimeOwnerId: "stale-owner", updatedAtMs: 17 }), false);
  sqlite.query("UPDATE _smithers_runs SET cancel_requested_at_ms = ? WHERE run_id = ?").run(18, "run-owned-usage");
  assert.equal(await persist({ ...upgraded, updatedAtMs: 18 }), false);
  sqlite.query("UPDATE _smithers_runs SET cancel_requested_at_ms = NULL WHERE run_id = ?").run("run-owned-usage");
  sqlite
    .query("UPDATE _smithers_attempts SET state = ? WHERE run_id = ? AND node_id = ? AND attempt = ?")
    .run("finished", "run-owned-usage", "node:usage", 1);
  assert.equal(await persist({ ...upgraded, updatedAtMs: 19 }), false);
}

async function assertOwnedUsageAtomicity(fixture: OwnedUsageFixture): Promise<void> {
  const { adapter, persist, tokenEvents, usageRowsForAttempt } = fixture;
  const event = {
    type: "TokenUsageReported",
    runId: "run-owned-usage",
    nodeId: "node:usage",
    iteration: 0,
    attempt: 2,
    model: "provider/model",
    agent: "PiAgent",
    inputTokens: 98,
    outputTokens: 99,
    timestampMs: 19
  };
  const row = {
    runId: "run-owned-usage",
    nodeId: "node:usage",
    iteration: 0,
    attempt: 2,
    runtimeOwnerId: "owner-a",
    model: "provider/model",
    agent: "PiAgent",
    inputTokens: 99,
    outputTokens: 99,
    updatedAtMs: 19
  };
  const eventsBeforeRejectedAttempt = tokenEvents().length;
  await assert.rejects(
    Promise.resolve(adapter.recordRunTokenUsageOwned({ ...row, event })),
    /does not match its normalized usage snapshot/u
  );
  assert.equal(tokenEvents().length, eventsBeforeRejectedAttempt);
  assert.equal(usageRowsForAttempt(2), 0);
  // A serialization failure after the upsert must roll the whole transaction back.
  const circularEvent: Record<string, unknown> = { ...event, inputTokens: 99 };
  circularEvent.self = circularEvent;
  await assert.rejects(Promise.resolve(adapter.recordRunTokenUsageOwned({ ...row, event: circularEvent })));
  assert.equal(usageRowsForAttempt(2), 0);
  assert.equal(
    await persist({
      attempt: 2,
      inputTokens: 3,
      freshInputTokens: 1,
      outputTokens: 2,
      cacheReadTokens: 2,
      cacheWriteTokens: 0,
      reasoningTokens: 1,
      costUsd: 0.25,
      updatedAtMs: 20
    }),
    true
  );
  assert.equal(tokenEvents().length, 7);
  assert.deepEqual(await adapter.getRunTokenUsage("run-owned-usage"), {
    runId: "run-owned-usage",
    inputTokens: 23,
    freshInputTokens: 9,
    outputTokens: 9,
    cacheReadTokens: 11,
    cacheWriteTokens: 1,
    reasoningTokens: 4,
    totalTokens: 32,
    costUsd: 1,
    pricedAttempts: 2,
    attempts: 2
  });
}

// Usage snapshots are cumulative within one attempt. The compatibility method
// must accept forward/equal snapshots, reject regressions, and atomically
// enforce the live run owner plus exact attempt and event.
bunAdapterTest("owned usage snapshots are fenced and component-monotonic", async () => {
  const fixture = await openOwnedUsageFixture();
  try {
    await assertOwnedUsageMonotonicity(fixture);
    await assertOwnedUsageAtomicity(fixture);
  } finally {
    fixture.close();
  }
});

// Keep creating the covering index for new databases. Do not force queries to
// use it: historical Smithers databases may predate the index and must remain
// resumable before any current startup migration runs.
test("event probe compatibility patch adds an optional covering index", async () => {
  const { SMITHERS_COMPATIBILITY_PATCHES } = await import("../src/smithers.js");
  const indexPatch = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "event_probe_index");
  assert.ok(indexPatch);
  assert.match(
    indexPatch.patched,
    /CREATE INDEX IF NOT EXISTS _smithers_events_insert_probe_v2_idx ON _smithers_events \(run_id, timestamp_ms, type, seq, payload_json\)/u
  );
  assert.equal(
    SMITHERS_COMPATIBILITY_PATCHES.some((patch) =>
      patch.patched.includes("INDEXED BY _smithers_events_insert_probe_v2_idx")
    ),
    false
  );
});

test("agent event ownership compatibility patch coalesces only an in-flight proof", async () => {
  const { SMITHERS_COMPATIBILITY_PATCHES } = await import("../src/smithers.js");
  const ownershipPatch = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "engine_agent_event_ownership");
  assert.ok(ownershipPatch);
  assert.match(ownershipPatch.patched, /let heartbeatOwnershipCheckInFlight = null/u);
  assert.match(
    ownershipPatch.patched,
    /if \(heartbeatOwnershipCheckInFlight\) return heartbeatOwnershipCheckInFlight/u
  );
  assert.match(ownershipPatch.patched, /const check = confirmHeartbeatOwnership\(\)\.finally/u);
  assert.match(ownershipPatch.patched, /const check = sharedHeartbeatOwnershipCheck\(\)/u);
  assert.match(
    ownershipPatch.patched,
    /if \(heartbeatOwnershipCheckInFlight === check\) heartbeatOwnershipCheckInFlight = null/u
  );
});

test("agent usage compatibility persists an owned snapshot before publishing telemetry", async () => {
  const { SMITHERS_COMPATIBILITY_PATCHES } = await import("../src/smithers.js");
  const progress = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "engine_agent_usage_progress");
  const mainInvocation = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "engine_main_usage_invocation");
  const jsonInvocation = SMITHERS_COMPATIBILITY_PATCHES.find(
    (patch) => patch.id === "engine_json_correction_usage_invocation"
  );
  const jsonResult = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "engine_json_correction_usage_result");
  const schemaInvocation = SMITHERS_COMPATIBILITY_PATCHES.find(
    (patch) => patch.id === "engine_schema_correction_usage_invocation"
  );
  const schemaResult = SMITHERS_COMPATIBILITY_PATCHES.find(
    (patch) => patch.id === "engine_schema_correction_usage_result"
  );
  const failed = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "engine_failed_usage_ownership");
  const final = SMITHERS_COMPATIBILITY_PATCHES.find((patch) => patch.id === "engine_final_usage_ownership");
  assert.ok(progress);
  assert.ok(mainInvocation);
  assert.ok(jsonInvocation);
  assert.ok(jsonResult);
  assert.ok(schemaInvocation);
  assert.ok(schemaResult);
  assert.ok(failed);
  assert.ok(final);
  const tokenEvent = progress.patched.indexOf('type: "TokenUsageReported"');
  const ownedWrite = progress.patched.indexOf("adapter.recordRunTokenUsageOwned({");
  const atomicEvent = progress.patched.indexOf("event: tokenUsageEvent", ownedWrite);
  const agentEvent = progress.patched.indexOf('type: "AgentEvent"', ownedWrite);
  const tokenPublication = progress.patched.indexOf("eventBus.emitEventQueued(tokenUsageEvent)", ownedWrite);
  assert.notEqual(tokenEvent, -1);
  assert.notEqual(ownedWrite, -1);
  assert.equal(tokenEvent < ownedWrite, true);
  assert.equal(atomicEvent > ownedWrite, true);
  assert.equal(agentEvent > ownedWrite, true);
  assert.equal(tokenPublication > agentEvent, true);
  assert.match(progress.patched, /runtimeOwnerId: executionOwnerId/u);
  assert.match(progress.patched, /if \(!stored\) return false/u);
  assert.match(mainInvocation.patched, /beginAgentUsageInvocation\(\);/u);
  assert.match(jsonInvocation.patched, /beginAgentUsageInvocation\(\);/u);
  assert.match(schemaInvocation.patched, /beginAgentUsageInvocation\(\);/u);
  assert.match(jsonResult.patched, /await persistAgentResultUsage\(retryResult\);/u);
  assert.match(schemaResult.patched, /await persistAgentResultUsage\(schemaRetryResult\);/u);
  assert.match(failed.patched, /await persistOwnedAgentUsage\(failedUsage/u);
  assert.match(final.patched, /await persistOwnedAgentUsage\(usage/u);
  assert.doesNotMatch(progress.patched, /adapter\.recordRunTokenUsage\(/u);
  assert.doesNotMatch(failed.patched, /adapter\.recordRunTokenUsage\(/u);
  assert.doesNotMatch(final.patched, /adapter\.recordRunTokenUsage\(/u);
});

async function patchedSmithersAgentUsageModules(): Promise<{
  extractUsageFromOutput: (raw: string) => Record<string, unknown> | undefined;
  usageFromCompletedEvent: (event: Record<string, unknown>) => Record<string, unknown> | undefined;
  OpenCodeAgent: new (options?: Record<string, unknown>) => {
    createOutputInterpreter: () => {
      onStdoutLine?: (line: string) => unknown[];
      onExit?: (result: Record<string, unknown>) => unknown[];
    };
  };
  CodexAgent: new (options?: Record<string, unknown>) => {
    buildCommand: (params: unknown) => Promise<Record<string, unknown>>;
    generate: (options: Record<string, unknown>) => Promise<{ text: string; usage?: unknown }>;
  };
}> {
  const { SMITHERS_COMPATIBILITY_PATCHES } = await import("../src/smithers.js");
  const pinnedAgentsSource = pinnedRunnerSourceDir("@smthrs/agents", "BaseCliAgent/BaseCliAgent");
  const pinnedAgentsRoot = path.dirname(pinnedAgentsSource);
  const isolatedAgentsRoot = path.join(tempProject(), "node_modules", "@smthrs", "agents");
  fs.mkdirSync(path.dirname(isolatedAgentsRoot), { recursive: true });
  fs.cpSync(pinnedAgentsRoot, isolatedAgentsRoot, { recursive: true });
  fs.rmSync(path.join(isolatedAgentsRoot, "node_modules"), { recursive: true, force: true });
  fs.symlinkSync(path.dirname(path.dirname(pinnedAgentsRoot)), path.join(isolatedAgentsRoot, "node_modules"), "dir");

  for (const patch of SMITHERS_COMPATIBILITY_PATCHES.filter(
    (candidate) => candidate.packageName === "@smthrs/agents"
  )) {
    const source = fs.readFileSync(path.join(isolatedAgentsRoot, ...patch.sourceRelativePath.split("/")), "utf8");
    assert.equal(source.split(patch.patched).length, 2, `${patch.id} is not installed in the pinned agents`);
  }
  // The copy only has to export a helper the installed agents keep private.
  const baseCliSourcePath = path.join(isolatedAgentsRoot, "src", "BaseCliAgent", "BaseCliAgent.js");
  const baseCliSource = fs.readFileSync(baseCliSourcePath, "utf8");
  assert.equal(baseCliSource.split("function usageFromCompletedEvent(").length, 2);
  fs.writeFileSync(
    baseCliSourcePath,
    baseCliSource.replace("function usageFromCompletedEvent(", "export function usageFromCompletedEvent("),
    "utf8"
  );

  const baseCli = (await import(
    pathToFileURL(path.join(isolatedAgentsRoot, "src", "BaseCliAgent", "BaseCliAgent.js")).href
  )) as {
    extractUsageFromOutput: (raw: string) => Record<string, unknown> | undefined;
    usageFromCompletedEvent: (event: Record<string, unknown>) => Record<string, unknown> | undefined;
  };
  const openCode = (await import(pathToFileURL(path.join(isolatedAgentsRoot, "src", "OpenCodeAgent.js")).href)) as {
    OpenCodeAgent: new (options?: Record<string, unknown>) => {
      createOutputInterpreter: () => {
        onStdoutLine?: (line: string) => unknown[];
        onExit?: (result: Record<string, unknown>) => unknown[];
      };
    };
  };
  const codex = (await import(pathToFileURL(path.join(isolatedAgentsRoot, "src", "CodexAgent.js")).href)) as {
    CodexAgent: new (options?: Record<string, unknown>) => {
      buildCommand: (params: unknown) => Promise<Record<string, unknown>>;
      generate: (options: Record<string, unknown>) => Promise<{ text: string; usage?: unknown }>;
    };
  };
  return {
    extractUsageFromOutput: baseCli.extractUsageFromOutput,
    usageFromCompletedEvent: baseCli.usageFromCompletedEvent,
    OpenCodeAgent: openCode.OpenCodeAgent,
    CodexAgent: codex.CodexAgent
  };
}

test("CLI usage compatibility canonicalizes provider-specific cache and reasoning semantics", async () => {
  const { extractUsageFromOutput, usageFromCompletedEvent, OpenCodeAgent } = await patchedSmithersAgentUsageModules();
  const canonical = {
    inputTokens: 21,
    outputTokens: 5,
    cacheReadTokens: 11,
    cacheWriteTokens: 3,
    freshInputTokens: 7,
    totalTokens: 26
  };
  const openCodeCanonical = { ...canonical, reasoningTokens: 2, reportedCostUsd: 0.125 };
  assert.equal(usageFromCompletedEvent({ usage: { inputTokens: 100, totalTokens: 150 } })?.totalTokens, 150);
  assert.equal(
    usageFromCompletedEvent({
      usage: {
        inputTokens: 100,
        inputTokenDetails: { noCacheTokens: 100, cacheReadTokens: "invalid" },
        outputTokens: 50
      }
    }),
    undefined
  );
  const claudeUsage = { input_tokens: 7, cache_read_input_tokens: 11, cache_creation_input_tokens: 3 };
  const claude = [
    JSON.stringify({ type: "message_start", message: { usage: claudeUsage } }),
    JSON.stringify({ type: "message_delta", usage: { output_tokens: 5 } }),
    JSON.stringify({ type: "result", usage: { ...claudeUsage, output_tokens: 5 } })
  ].join("\n");
  assert.deepEqual(extractUsageFromOutput(claude), canonical);
  assert.deepEqual(
    extractUsageFromOutput(JSON.stringify({ type: "result", usage: { ...claudeUsage, output_tokens: 5 } })),
    canonical
  );
  assert.deepEqual(
    extractUsageFromOutput(
      JSON.stringify({
        type: "turn.completed",
        usage: {
          input_tokens: 21,
          cached_input_tokens: 11,
          cache_write_input_tokens: 3,
          output_tokens: 5
        }
      })
    ),
    canonical
  );
  assert.deepEqual(
    extractUsageFromOutput(
      JSON.stringify({
        type: "step_finish",
        part: {
          cost: 0.125,
          tokens: { input: 7, output: 3, reasoning: 2, cache: { read: 11, write: 3 }, total: 999 }
        }
      })
    ),
    openCodeCanonical
  );
  assert.deepEqual(
    extractUsageFromOutput(
      JSON.stringify({
        type: "step_finish",
        part: { cost: 0.01, tokens: { input: 0, output: 0, reasoning: 0, cache: { read: 0, write: 0 } } }
      })
    ),
    {
      inputTokens: 0,
      outputTokens: 0,
      totalTokens: 0,
      reasoningTokens: 0,
      cacheReadTokens: 0,
      cacheWriteTokens: 0,
      freshInputTokens: 0,
      reportedCostUsd: 0.01
    }
  );
  assert.deepEqual(
    extractUsageFromOutput(
      JSON.stringify({
        type: "step_finish",
        part: { tokens: { input: 7, output: 3, reasoning: 2, cache: { read: 11, write: 3 } } }
      })
    ),
    { ...canonical, reasoningTokens: 2 }
  );
  assert.equal(
    extractUsageFromOutput(
      JSON.stringify({ type: "step_finish", part: { cost: 0.125, tokens: { input: "7", output: 5 } } })
    ),
    undefined
  );
  const openCode = new OpenCodeAgent();
  const interpreter = openCode.createOutputInterpreter();
  const completed = interpreter.onStdoutLine?.(
    JSON.stringify({
      type: "step_finish",
      part: {
        reason: "stop",
        cost: 0.125,
        tokens: { input: 7, output: 3, reasoning: 2, cache: { read: 11, write: 3 }, total: 999 }
      }
    })
  );
  assert.deepEqual(
    completed?.find((event) => (event as { type?: unknown }).type === "completed"),
    {
      type: "completed",
      engine: "opencode",
      ok: true,
      answer: undefined,
      resume: undefined,
      usage: openCodeCanonical
    }
  );

  const failedInterpreter = openCode.createOutputInterpreter();
  failedInterpreter.onStdoutLine?.(
    JSON.stringify({
      type: "step_finish",
      part: {
        reason: "tool-calls",
        cost: 0.125,
        tokens: { input: 7, output: 3, reasoning: 2, cache: { read: 11, write: 3 }, total: 999 }
      }
    })
  );
  const failed = failedInterpreter.onStdoutLine?.(
    JSON.stringify({ type: "error", error: { name: "ProviderError", data: { message: "failed" } } })
  );
  assert.deepEqual(
    (failed?.find((event) => (event as { type?: unknown }).type === "completed") as { usage?: unknown }).usage,
    {
      ...openCodeCanonical
    }
  );
});

