test("syncRun uses durable event sequence for the current accounting segment", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);

  const workflowRunId = "ultrafuzz-sequenced-usage";
  const event = (seq: number, timestampMs: number, type: string, payload: Record<string, unknown> = {}) =>
    JSON.stringify({
      runId: workflowRunId,
      seq,
      timestampMs,
      type,
      payload: { runId: workflowRunId, timestampMs, type, ...payload }
    });
  const events = `${[
    event(0, 100, "NodeStarted", { nodeId: "node:project-discovery", iteration: 0, attempt: 1 }),
    event(1, 300, "TokenUsageReported", {
      nodeId: "node:project-discovery",
      iteration: 0,
      attempt: 1,
      inputTokens: 10,
      outputTokens: 0,
      cacheReadTokens: 0,
      cacheWriteTokens: 0,
      reasoningTokens: 0,
      model: "superseded-model",
      agent: "generated-agent"
    }),
    event(2, 200, "TokenUsageReported", {
      nodeId: "node:project-discovery",
      iteration: 0,
      attempt: 1,
      inputTokens: 20,
      outputTokens: 0,
      cacheReadTokens: 0,
      cacheWriteTokens: 0,
      reasoningTokens: 0,
      model: "gpt-authoritative-model",
      agent: "generated-agent"
    }),
    // A replay after the owned DB write committed but its first event publish
    // failed is still one cumulative attempt, never a second billed response.
    event(3, 350, "TokenUsageReported", {
      nodeId: "node:project-discovery",
      iteration: 0,
      attempt: 1,
      inputTokens: 20,
      outputTokens: 0,
      cacheReadTokens: 0,
      cacheWriteTokens: 0,
      reasoningTokens: 0,
      model: "gpt-authoritative-model",
      agent: "generated-agent"
    }),
    event(4, 400, "NodeFinished", { nodeId: "node:project-discovery", iteration: 0, attempt: 1 }),
    event(5, 500, "RunFinished")
  ].join("\n")}\n`;
  const env = fakeLifecycleSmithersEnv(project, {
    inspect: workflowInspect({
      workflowRunId,
      steps: [{ id: "node:project-discovery", state: "finished", attempt: 1 }]
    }),
    events
  });
  env.ULTRAFUZZ_PRICING_CATALOG_URL = pricingCatalogDataUrl({
    openai: {
      models: {
        "gpt-authoritative-model": { cost: { input: 1, output: 1, cache_read: 0.5, cache_write: 1.5 } }
      }
    }
  });
  const run = await startRun({ projectRoot: project, runId: "sequenced-usage", env });
  assert.equal(run.ok, true, JSON.stringify(run.diagnostics));
  writeRequiredArtifactSet(run.value!.run_root, "project-discovery", ["setup/project-discovery.md", "findings.json"]);

  const sync = await syncRun({ projectRoot: project, runId: "sequenced-usage", env });
  assert.equal(sync.ok, true, JSON.stringify(sync.diagnostics));
  const metadata = JSON.parse(fs.readFileSync(path.join(run.value!.run_root, "run.json"), "utf8")) as {
    accounting?: {
      current?: {
        control_generation?: string;
        source_event_sequences?: number[];
        total_tokens?: number;
        event_count?: number;
        attempts?: unknown[];
      };
      segments?: Array<{ control_generation?: string; source_event_sequences?: number[]; total_tokens?: number }>;
      pricing_catalog?: { resolved_models?: string[]; unresolved_models?: string[] };
    };
  };
  assert.equal(metadata.accounting?.segments?.length, 1);
  assert.deepEqual(metadata.accounting?.current?.source_event_sequences, [1, 2, 3]);
  assert.equal(metadata.accounting?.current?.total_tokens, 20);
  assert.equal(metadata.accounting?.current?.event_count, 1);
  assert.equal(metadata.accounting?.current?.attempts?.length, 1);
  assert.deepEqual(metadata.accounting?.pricing_catalog?.resolved_models, ["gpt-authoritative-model"]);
  assert.deepEqual(metadata.accounting?.pricing_catalog?.unresolved_models, []);
  assert.match(metadata.accounting?.current?.control_generation ?? "", /^[a-f0-9]{64}$/u);
  assert.equal(
    metadata.accounting?.segments?.[0]?.control_generation,
    metadata.accounting?.current?.control_generation
  );
});

test("syncRun appends unseen usage events to the current control segment", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);

  const workflowRunId = "ultrafuzz-implicit-usage";
  const tokenEvent = (inputTokens: number, outputTokens: number, model: string) => ({
    type: "TokenUsageReported",
    nodeId: "node:project-discovery",
    attempt: 1,
    extra: {
      iteration: 0,
      inputTokens,
      outputTokens,
      model,
      agent: "generated-agent"
    }
  });
  const firstSegment = [
    { type: "NodeStarted", nodeId: "node:project-discovery", attempt: 1, extra: { iteration: 0 } },
    tokenEvent(10, 5, "gpt-initial-model"),
    { type: "NodeFinished", nodeId: "node:project-discovery", attempt: 1, extra: { iteration: 0 } },
    { type: "RunFinished" }
  ];
  const env = fakeLifecycleSmithersEnv(project, {
    inspect: workflowInspect({
      workflowRunId,
      steps: [{ id: "node:project-discovery", state: "finished", attempt: 1 }]
    }),
    events: workflowEvents(workflowRunId, firstSegment)
  });
  env.ULTRAFUZZ_PRICING_CATALOG_URL = pricingCatalogDataUrl({
    openai: {
      models: {
        "gpt-initial-model": { cost: { input: 1, output: 1 } },
        "gpt-replacement-model": { cost: { input: 2, output: 2 } }
      }
    }
  });
  const run = await startRun({ projectRoot: project, runId: "implicit-usage", env });
  assert.equal(run.ok, true, JSON.stringify(run.diagnostics));
  const runRoot = run.value?.run_root;
  assert.ok(runRoot);
  writeRequiredArtifactSet(runRoot, "project-discovery", ["setup/project-discovery.md", "findings.json"]);

  const first = await syncRun({ projectRoot: project, runId: "implicit-usage", env });
  assert.equal(first.ok, true, JSON.stringify(first.diagnostics));
  const firstMetadata = JSON.parse(fs.readFileSync(path.join(runRoot, "run.json"), "utf8")) as {
    accounting?: { pricing_catalog?: { resolved_models?: string[]; model_prices?: Record<string, unknown> } };
  };
  assert.deepEqual(firstMetadata.accounting?.pricing_catalog?.resolved_models, ["gpt-initial-model"]);
  assert.deepEqual(Object.keys(firstMetadata.accounting?.pricing_catalog?.model_prices ?? {}), ["gpt-initial-model"]);

  fs.writeFileSync(
    path.join(project, "fake-smithers-events.ndjson"),
    workflowEvents(workflowRunId, [...firstSegment, tokenEvent(20, 10, "gpt-replacement-model")]),
    "utf8"
  );
  const second = await syncRun({ projectRoot: project, runId: "implicit-usage", env });
  const replayed = await syncRun({ projectRoot: project, runId: "implicit-usage", env });
  assert.equal(second.ok, true, JSON.stringify(second.diagnostics));
  assert.equal(replayed.ok, true, JSON.stringify(replayed.diagnostics));

  const metadata = JSON.parse(fs.readFileSync(path.join(runRoot, "run.json"), "utf8")) as {
    accounting?: {
      segments?: Array<{
        control_generation?: string;
        source_event_sequences?: number[];
        total_tokens?: number;
        event_count?: number;
      }>;
      cumulative?: { total_tokens?: number; event_count?: number };
      pricing_catalog?: { resolved_models?: string[]; model_prices?: Record<string, unknown> };
    };
  };
  const segments = metadata.accounting?.segments ?? [];
  assert.equal(segments.length, 1);
  assert.equal(segments[0]?.total_tokens, 30);
  assert.equal(segments[0]?.event_count, 1);
  assert.deepEqual(segments[0]?.source_event_sequences, [1, 4]);
  assert.match(segments[0]?.control_generation ?? "", /^[a-f0-9]{64}$/u);
  assert.equal(metadata.accounting?.cumulative?.total_tokens, 30);
  assert.equal(metadata.accounting?.cumulative?.event_count, 1);
  assert.deepEqual(metadata.accounting?.pricing_catalog?.resolved_models, ["gpt-replacement-model"]);
  assert.deepEqual(Object.keys(metadata.accounting?.pricing_catalog?.model_prices ?? {}), ["gpt-replacement-model"]);
  assert.equal(fs.readFileSync(path.join(runRoot, "usage.jsonl"), "utf8").trim().split("\n").length, 2);
});

test("syncRun reports a malformed usage ledger without blocking run status", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project, GENERIC_RUNTIME_MARKDOWN_PATH);

  const workflowRunId = "ultrafuzz-malformed-only-usage";
  const env = fakeLifecycleSmithersEnv(project, {
    inspect: workflowInspect({
      workflowRunId,
      steps: [{ id: "node:project-discovery", state: "finished", attempt: 1 }]
    }),
    events: workflowEvents(workflowRunId, [
      { type: "NodeStarted", nodeId: "node:project-discovery", attempt: 1, extra: { iteration: 0 } },
      { type: "NodeFinished", nodeId: "node:project-discovery", attempt: 1, extra: { iteration: 0 } },
      { type: "RunFinished" }
    ])
  });
  const run = await startRun({ projectRoot: project, runId: "malformed-only-usage", env });
  assert.equal(run.ok, true, JSON.stringify(run.diagnostics));
  assert.ok(run.value);
  writeRequiredArtifactSet(run.value.run_root, "project-discovery", [GENERIC_RUNTIME_MARKDOWN_PATH, "findings.json"]);
  fs.writeFileSync(path.join(run.value.run_root, "usage.jsonl"), "{malformed\n", "utf8");

  const usagePath = path.join(run.value.run_root, "usage.jsonl");
  const usageBefore = fs.readFileSync(usagePath);
  const metadataBefore = fs.readFileSync(path.join(run.value.run_root, "run.json"));

  const sync = await syncRun({ projectRoot: project, runId: "malformed-only-usage", env });

  assert.equal(sync.ok, true, JSON.stringify(sync.diagnostics));
  assert.equal(sync.value?.status, "succeeded", JSON.stringify(sync.diagnostics));
  const warnings = sync.diagnostics.filter((diagnostic) => diagnostic.code === "WORKFLOW_ACCOUNTING_FAILED");
  assert.deepEqual(
    warnings.map((diagnostic) => diagnostic.severity),
    ["warning"]
  );
  assert.match(warnings[0]?.message ?? "", /usage ledger record 1 is invalid strict JSON/u);
  assert.deepEqual(fs.readFileSync(usagePath), usageBefore);
  assert.deepEqual(fs.readFileSync(path.join(run.value.run_root, "run.json")), metadataBefore);
});

