test("syncRun lets a model fan-out aggregate follow its reopened skipped attempts to success", async () => {
  const project = tempProject();
  writeFanoutProject(project, GENERIC_RUNTIME_MARKDOWN_PATH);
  const runId = "sync-fanout-reopened";
  const workflowRunId = `ultrafuzz-${runId}`;
  const discoveryFast = "node:project-discovery__model_0__attempt_0";
  const discoveryDeep = "node:project-discovery__model_1__attempt_1";
  // Each analysis attempt consumes both discovery attempts, so one failed discovery skips both.
  const analysisFast = "node:signal-analysis__model_0__attempt_0";
  const analysisDeep = "node:signal-analysis__model_1__attempt_1";
  const fast = { chainIndex: 0, profileId: "fast", model: "gpt-test-fast" };
  const deep = { chainIndex: 0, profileId: "deep", model: "gpt-test-deep" };
  const attemptSelections = {
    [discoveryFast]: { 1: fast },
    [discoveryDeep]: { 1: deep, 2: deep },
    [analysisFast]: { 1: fast },
    [analysisDeep]: { 1: deep }
  };
  const failedEvents = [
    { type: "NodeStarted", nodeId: discoveryFast, attempt: 1 },
    { type: "NodeFinished", nodeId: discoveryFast, attempt: 1 },
    { type: "NodeStarted", nodeId: discoveryDeep, attempt: 1 },
    { type: "NodeFailed", nodeId: discoveryDeep, attempt: 1, error: { message: "model failed" } },
    { type: "NodeSkipped", nodeId: analysisFast, attempt: 1 },
    { type: "NodeSkipped", nodeId: analysisDeep, attempt: 1 }
  ];
  const env = fakeLifecycleSmithersEnv(project, {
    inspect: workflowInspect({
      workflowRunId,
      status: "failed",
      state: "failed",
      steps: [
        { id: discoveryFast, state: "finished", attempt: 1 },
        { id: discoveryDeep, state: "failed", attempt: 1 },
        { id: analysisFast, state: "skipped", attempt: 1 },
        { id: analysisDeep, state: "skipped", attempt: 1 }
      ]
    }),
    events: workflowEvents(workflowRunId, failedEvents),
    attemptSelections
  });
  const run = await startRun({ projectRoot: project, runId, env });
  assert.equal(run.ok, true, JSON.stringify(run.diagnostics));
  assert.ok(run.value);
  const runRoot = run.value.run_root;
  const statePath = path.join(runRoot, "state.json");
  const writeAttemptArtifacts = (taskId: string): void => {
    const attemptId = taskId.slice("node:".length);
    const primary = attemptId.startsWith("project-discovery") ? GENERIC_RUNTIME_MARKDOWN_PATH : "signal-analysis.md";
    writeRequiredArtifactSet(runRoot, attemptId, [primary, "findings.json"]);
  };
  writeAttemptArtifacts(discoveryFast);

  const failed = await syncRun({ projectRoot: project, runId, env });
  assert.equal(failed.ok, true, JSON.stringify(failed.diagnostics));
  assert.equal(failed.value?.status, "failed");
  assert.equal(readRunState(statePath).nodes["project-discovery"]?.status, "failed");
  assert.equal(readRunState(statePath).nodes["signal-analysis"]?.status, "skipped");

  // The runner now reports what `resume --retry-failed` produces: the failed discovery attempt ran
  // again, and both analysis attempts skipped behind it reopened and finished.
  const recoveredEnv = fakeLifecycleSmithersEnv(project, {
    inspect: workflowInspect({
      workflowRunId,
      steps: [
        { id: discoveryFast, state: "finished", attempt: 1 },
        { id: discoveryDeep, state: "finished", attempt: 2 },
        { id: analysisFast, state: "finished", attempt: 1 },
        { id: analysisDeep, state: "finished", attempt: 1 }
      ]
    }),
    events: workflowEvents(workflowRunId, [
      ...failedEvents,
      { type: "NodeStarted", nodeId: discoveryDeep, attempt: 2 },
      { type: "NodeFinished", nodeId: discoveryDeep, attempt: 2 },
      { type: "NodeStarted", nodeId: analysisFast, attempt: 1 },
      { type: "NodeFinished", nodeId: analysisFast, attempt: 1 },
      { type: "NodeStarted", nodeId: analysisDeep, attempt: 1 },
      { type: "NodeFinished", nodeId: analysisDeep, attempt: 1 }
    ]),
    attemptSelections
  });
  for (const taskId of [discoveryDeep, analysisFast, analysisDeep]) writeAttemptArtifacts(taskId);

  const recovered = await syncRun({ projectRoot: project, runId, env: recoveredEnv });
  assert.equal(recovered.ok, true, JSON.stringify(recovered.diagnostics));
  const nodes = readRunState(statePath).nodes;
  assert.equal(nodes["signal-analysis__model_0__attempt_0"]?.status, "succeeded");
  assert.equal(nodes["signal-analysis__model_1__attempt_1"]?.status, "succeeded");
  assert.equal(nodes["project-discovery"]?.status, "succeeded");
  assert.equal(nodes["signal-analysis"]?.status, "succeeded");
  assert.equal(recovered.value?.status, "succeeded", JSON.stringify(recovered.diagnostics));
});

test("controller refresh selects current source without rewriting historical evidence", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);
  const runId = "controller-refresh-success";
  const env = controllerRefreshTerminalEnv(project, runId, { enforceWorkflowChangeAcceptance: true });
  const launched = await startRun({ projectRoot: project, runId, env });
  assert.equal(launched.ok, true, JSON.stringify(launched.diagnostics));

  const metadataPath = path.join(launched.value!.run_root, "run.json");
  const statePath = path.join(launched.value!.run_root, "state.json");
  const journalPath = path.join(launched.value!.run_root, "smithers", "workflow-run-link-journal.json");
  const resolvedConfigPath = path.join(launched.value!.run_root, "smithers", "resolved-config.json");
  const tasksPath = path.join(launched.value!.run_root, "smithers", "tasks.json");
  const smithersGraphPath = path.join(launched.value!.run_root, "smithers", "expanded-graph.json");
  const canonicalGraphPath = path.join(launched.value!.run_root, "graph.json");
  const metadata = JSON.parse(fs.readFileSync(metadataPath, "utf8")) as {
    workflow?: { path?: string; run_id?: string };
  };
  assert.ok(metadata.workflow?.path);
  const historicalWorkflowPath = path.join(project, metadata.workflow.path);
  const historicalWorkflow = fs.readFileSync(historicalWorkflowPath);
  const historicalConfig = JSON.parse(fs.readFileSync(resolvedConfigPath, "utf8")) as {
    run: Record<string, unknown>;
  };
  historicalConfig.run.maxParallelNodes = 8;
  fs.writeFileSync(resolvedConfigPath, `${JSON.stringify(historicalConfig, null, 2)}\n`, "utf8");
  const tasks = JSON.parse(fs.readFileSync(tasksPath, "utf8")) as SmithersTaskManifestDocument;
  const referencedAttempts = new Set(
    tasks.tasks.flatMap((task) => task.dependencyArtifactDirs.map((directory) => path.basename(directory)))
  );
  const leafTask = tasks.tasks.find((task) => !referencedAttempts.has(task.attemptId));
  assert.ok(leafTask);
  leafTask.metadata.node.group = "continuation-leaf";
  fs.writeFileSync(tasksPath, `${JSON.stringify(tasks, null, 2)}\n`, "utf8");
  const canonicalGraph = JSON.parse(fs.readFileSync(canonicalGraphPath, "utf8")) as {
    groups: Record<string, unknown>;
  };
  canonicalGraph.groups["continuation-leaf"] = { defaults: { failure_policy: "continue" } };
  fs.writeFileSync(canonicalGraphPath, `${JSON.stringify(canonicalGraph, null, 2)}\n`, "utf8");
  fs.rmSync(smithersGraphPath);
  const retainedConfig = fs.readFileSync(resolvedConfigPath);
  const retainedMetadata = fs.readFileSync(metadataPath);
  const retainedJournal = fs.readFileSync(journalPath);
  fs.writeFileSync(env.SMITHERS_FAKE_LOG!, "", "utf8");

  const refreshed = await resumeRun({ projectRoot: project, runId, refreshController: true, env });

  assert.equal(refreshed.ok, true, JSON.stringify(refreshed.diagnostics));
  assert.equal(refreshed.value?.run_id, runId);
  assert.equal(refreshed.value?.workflow_run_id, metadata.workflow.run_id);
  const command = fs.readFileSync(env.SMITHERS_FAKE_LOG!, "utf8").trim();
  const commands = command.split("\n");
  assert.equal(commands[0], `inspect ${metadata.workflow.run_id} --format json --full-output`);
  assert.match(
    commands[1] ?? "",
    /\.smithers\/continuations\/[0-9a-f-]+\/workflows\/ultrafuzz-controller-refresh-success\.tsx/u
  );
  assert.match(
    commands[1] ?? "",
    new RegExp(
      `--resume ${metadata.workflow.run_id} --run-id ${metadata.workflow.run_id} .*--accept-workflow-change`,
      "u"
    )
  );
  const continuationPath = /^up (\S+)/u.exec(commands[1] ?? "")?.[1];
  assert.ok(continuationPath);
  assert.equal(fs.existsSync(continuationPath), true);
  const continuationSource = fs.readFileSync(continuationPath, "utf8");
  const specsPrefix = "const serializedTaskSpecs = ";
  const specsStart = continuationSource.indexOf(specsPrefix);
  const specsEnd = continuationSource.indexOf(" as const;", specsStart);
  assert.ok(specsStart >= 0 && specsEnd > specsStart, continuationSource);
  const specs = JSON.parse(continuationSource.slice(specsStart + specsPrefix.length, specsEnd)) as Array<{
    attemptId: string;
    continueOnFail: boolean;
  }>;
  assert.equal(specs.find((task) => task.attemptId === leafTask.attemptId)?.continueOnFail, true);
  assert.deepEqual(fs.readFileSync(historicalWorkflowPath), historicalWorkflow);
  assert.deepEqual(fs.readFileSync(resolvedConfigPath), retainedConfig);
  assert.deepEqual(fs.readFileSync(metadataPath), retainedMetadata);
  assert.deepEqual(fs.readFileSync(journalPath), retainedJournal);
  const continuedState = JSON.parse(fs.readFileSync(statePath, "utf8")) as RunState;
  assert.equal(continuedState.status, "running");
  assert.equal(continuedState.finished_at, undefined);

  fs.rmSync(historicalWorkflowPath);
  fs.writeFileSync(env.SMITHERS_FAKE_LOG!, "", "utf8");
  const refreshedWithoutHistoricalProjectWorkflow = await resumeRun({
    projectRoot: project,
    runId,
    refreshController: true,
    env
  });
  assert.equal(
    refreshedWithoutHistoricalProjectWorkflow.ok,
    true,
    JSON.stringify(refreshedWithoutHistoricalProjectWorkflow.diagnostics)
  );
});

test("a refresh resume reuses its own ownership inspection instead of inspecting twice", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);
  const runId = "controller-refresh-single-inspect";
  const smithersRunId = `ultrafuzz-${runId}`;
  const inspectCommand = `inspect ${smithersRunId} --format json --full-output`;
  const env = controllerRefreshTerminalEnv(project, runId);
  const launched = await startRun({ projectRoot: project, runId, env });
  assert.equal(launched.ok, true, JSON.stringify(launched.diagnostics));
  const issuedCommands = (): string[] => fs.readFileSync(env.SMITHERS_FAKE_LOG!, "utf8").trim().split("\n");

  fs.writeFileSync(env.SMITHERS_FAKE_LOG!, "", "utf8");
  const refreshed = await resumeRun({ projectRoot: project, runId, refreshController: true, env });

  assert.equal(refreshed.ok, true, JSON.stringify(refreshed.diagnostics));
  assert.equal(refreshed.value?.submitted, true);
  const refreshCommands = issuedCommands();
  // Refresh proves ownership before rendering, and the resume behind it reuses
  // that evidence. A second inspect would be a redundant subprocess per refresh
  // and would re-derive ownership from a run the renderer has already touched.
  assert.deepEqual(
    refreshCommands.filter((command) => command.startsWith("inspect ")),
    [inspectCommand]
  );
  assert.equal(refreshCommands[0], inspectCommand);
  assert.match(refreshCommands[1] ?? "", new RegExp(`^up .*--resume ${smithersRunId} --run-id ${smithersRunId} `, "u"));

  // The reused inspection is still the authority for explicit failed-task
  // recovery: a retrying refresh resets its failed node off one inspect.
  fs.writeFileSync(env.SMITHERS_FAKE_LOG!, "", "utf8");
  const retried = await resumeRun({ projectRoot: project, runId, refreshController: true, retryFailed: true, env });
  assert.equal(retried.ok, true, JSON.stringify(retried.diagnostics));
  const retryCommands = issuedCommands();
  assert.deepEqual(
    retryCommands.filter((command) => command.startsWith("inspect ")),
    [inspectCommand]
  );
  assert.equal(
    retryCommands.some((command) => command.startsWith("timetravel ")),
    true,
    retryCommands.join("\n")
  );

  // An ordinary resume has no refresh inspection to inherit, so it performs its
  // own ownership check — exactly one, never zero and never two.
  fs.writeFileSync(env.SMITHERS_FAKE_LOG!, "", "utf8");
  const ordinary = await resumeRun({ projectRoot: project, runId, env });
  assert.equal(ordinary.ok, true, JSON.stringify(ordinary.diagnostics));
  assert.deepEqual(
    issuedCommands().filter((command) => command.startsWith("inspect ")),
    [inspectCommand]
  );
});

test("resume refuses a run planned for removed per-node cloud execution before invoking Smithers", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);
  const runId = "removed-cloud-execution-resume";
  const env = controllerRefreshTerminalEnv(project, runId);
  const fakeLog = env.SMITHERS_FAKE_LOG;
  assert.ok(fakeLog);
  const launched = await startRun({ projectRoot: project, runId, env });
  assert.ok(launched.ok && launched.value !== undefined, JSON.stringify(launched.diagnostics));
  // Record what the pre-removal launch wrote for `[execution] mode = "cloud"`: the resolved config
  // and every task in the task manifest carry the cloud mode and the Modal provider settings.
  const modal = {
    app: "ultrafuzz-test",
    image: "ultrafuzz-test",
    credentialEnv: ["MODAL_TOKEN_ID", "MODAL_TOKEN_SECRET"]
  };
  const configPath = path.join(launched.value.run_root, "smithers", "resolved-config.json");
  const config = parseResolvedConfigJsonBytes(fs.readFileSync(configPath));
  fs.writeFileSync(
    configPath,
    serializeResolvedConfigJsonBytes({
      ...config,
      execution: { ...config.execution, mode: "cloud", provider: "modal", providers: { modal } }
    })
  );
  const tasksPath = path.join(launched.value.run_root, "smithers", "tasks.json");
  const tasks = JSON.parse(fs.readFileSync(tasksPath, "utf8")) as SmithersTaskManifestDocument;
  for (const task of tasks.tasks) {
    task.execution = { ...task.execution, mode: "cloud", provider: "modal", modal };
    task.metadata.execution = { ...task.metadata.execution, mode: "cloud", provider: "modal" };
  }
  fs.writeFileSync(tasksPath, `${JSON.stringify(tasks, null, 2)}\n`, "utf8");

  const assertRefused = async (manifest: string) => {
    for (const refreshController of [false, true]) {
      fs.writeFileSync(fakeLog, "", "utf8");
      const resumed = await resumeRun({ projectRoot: project, runId, refreshController, env });
      const label = `${manifest} task manifest, refreshController=${String(refreshController)}`;
      assert.equal(resumed.ok, false, label);
      assert.deepEqual(
        resumed.diagnostics.map((diagnostic) => diagnostic.code),
        ["WORKFLOW_CLOUD_EXECUTION_REMOVED"],
        `${label}: ${JSON.stringify(resumed.diagnostics)}`
      );
      assert.equal(fs.readFileSync(fakeLog, "utf8"), "", `${label}: no Smithers command runs`);
    }
  };
  await assertRefused("cloud");
  // The config decides, so a task manifest that cannot be read does not let the run through.
  fs.writeFileSync(tasksPath, "{", "utf8");
  await assertRefused("malformed");
  fs.rmSync(tasksPath);
  await assertRefused("missing");
});

test("a plain resume refuses a workflow rendered before task preparation took the planned schema bundle", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);
  const runId = "resume-pre-planned-schema-workflow";
  const env = controllerRefreshTerminalEnv(project, runId);
  const fakeLog = env.SMITHERS_FAKE_LOG;
  assert.ok(fakeLog);
  const launched = await startRun({ projectRoot: project, runId, env });
  assert.equal(launched.ok, true, JSON.stringify(launched.diagnostics));
  const workflowPath = path.join(project, ".smithers", "workflows", `ultrafuzz-${runId}.tsx`);
  const rendered = fs.readFileSync(workflowPath, "utf8");
  const current = "materializePromptSchemas(schemaDirectory, bundle)";
  assert.ok(rendered.includes(current), "the current template no longer materializes the planned bundle this way");
  const workflowMode = fs.statSync(workflowPath).mode & 0o777;

  // The launch workflows of earlier releases still call the old signature (#983, and before it), which
  // this release's installed modules reject in every task preparation. Resume stops before Smithers
  // starts, so no task fails, and names the refresh that renders the current workflow.
  for (const earlier of [
    "materializePromptSchemas(schemaDirectory, { replaceExisting: replacePromptSchemas })",
    "materializePromptSchemas(schemaDirectory)"
  ]) {
    fs.chmodSync(workflowPath, 0o600);
    fs.writeFileSync(workflowPath, rendered.replace(current, earlier), "utf8");
    fs.chmodSync(workflowPath, workflowMode);
    fs.writeFileSync(fakeLog, "", "utf8");
    const resumed = await resumeRun({ projectRoot: project, runId, env });
    assert.equal(resumed.ok, false, earlier);
    assert.deepEqual(
      resumed.diagnostics.map((diagnostic) => diagnostic.code),
      ["WORKFLOW_CONTROLLER_REFRESH_REQUIRED"],
      `${earlier}: ${JSON.stringify(resumed.diagnostics)}`
    );
    assert.match(
      resumed.diagnostics[0]?.message ?? "",
      new RegExp(`ultrafuzz resume ${runId} --refresh-controller`, "u")
    );
    assert.equal(fs.readFileSync(fakeLog, "utf8"), "", `${earlier}: no Smithers command runs`);
  }
  const refreshed = await resumeRun({ projectRoot: project, runId, refreshController: true, env });
  assert.equal(refreshed.ok, true, JSON.stringify(refreshed.diagnostics));
  assert.equal(refreshed.value?.submitted, true);
});

test("resume refuses a run whose resolved config cannot be read instead of continuing it locally", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);
  const runId = "unreadable-config-resume";
  const env = controllerRefreshTerminalEnv(project, runId);
  const fakeLog = env.SMITHERS_FAKE_LOG;
  assert.ok(fakeLog);
  const launched = await startRun({ projectRoot: project, runId, env });
  assert.ok(launched.ok && launched.value !== undefined, JSON.stringify(launched.diagnostics));
  const configPath = path.join(launched.value.run_root, "smithers", "resolved-config.json");
  const localConfig = fs.readFileSync(configPath);

  // The task manifest still records a local run; without the config resume cannot confirm it.
  for (const [label, damage] of [
    ["malformed", () => fs.writeFileSync(configPath, "{", "utf8")],
    ["missing", () => fs.rmSync(configPath)]
  ] as const) {
    damage();
    for (const refreshController of [false, true]) {
      fs.writeFileSync(fakeLog, "", "utf8");
      const resumed = await resumeRun({ projectRoot: project, runId, refreshController, env });
      const context = `${label} config, refreshController=${String(refreshController)}`;
      assert.equal(resumed.ok, false, context);
      assert.deepEqual(
        resumed.diagnostics.map((diagnostic) => diagnostic.code),
        ["WORKFLOW_LIFECYCLE_FAILED"],
        `${context}: ${JSON.stringify(resumed.diagnostics)}`
      );
      assert.match(
        resumed.diagnostics[0]?.message ?? "",
        new RegExp(`^run ${runId} cannot be resumed without its resolved config, which records whether`, "u"),
        context
      );
      assert.equal(fs.readFileSync(fakeLog, "utf8"), "", `${context}: no Smithers command runs`);
    }
  }

  fs.writeFileSync(configPath, localConfig);
  const resumed = await resumeRun({ projectRoot: project, runId, env });
  assert.equal(resumed.ok, true, JSON.stringify(resumed.diagnostics));
  assert.match(fs.readFileSync(fakeLog, "utf8"), /--resume ultrafuzz-unreadable-config-resume /u);
});

testWhen(runningUnderBun)(
  "engine-owned task runtime crosses sealed issuer aliases under production Bun symlink flags",
  () => {
    const root = tempProject();
    const controls = path.join(root, "controls");
    const driverRoot = path.join(root, "dependencies", "packages", "driver");
    const engineRoot = path.join(root, "dependencies", "packages", "engine");
    fs.mkdirSync(controls, { recursive: true });
    fs.mkdirSync(driverRoot, { recursive: true });
    fs.mkdirSync(engineRoot, { recursive: true });
    fs.writeFileSync(path.join(controls, "bunfig.toml"), "\n", "utf8");
    fs.writeFileSync(path.join(controls, "bun-empty.env"), "\n", "utf8");
    fs.writeFileSync(
      path.join(driverRoot, "package.json"),
      `${JSON.stringify({
        name: "@smthrs/driver",
        type: "module",
        exports: { "./task-runtime": "./task-runtime.js" }
      })}\n`,
      "utf8"
    );
    fs.writeFileSync(
      path.join(driverRoot, "task-runtime.js"),
      `import { AsyncLocalStorage } from "node:async_hooks";
const storage = new AsyncLocalStorage();
export const withTaskRuntime = (runtime, execute) => storage.run(runtime, execute);
export const getTaskRuntime = () => storage.getStore();
`,
      "utf8"
    );
    fs.writeFileSync(
      path.join(engineRoot, "package.json"),
      `${JSON.stringify({ name: "@smthrs/engine", type: "module", exports: { ".": "./engine.js" } })}\n`,
      "utf8"
    );
    fs.writeFileSync(
      path.join(engineRoot, "engine.js"),
      `import { withTaskRuntime } from "@smthrs/driver/task-runtime";
export const execute = (agent) => {
  const runtime = {
    runId: "sealed-run",
    stepId: "final-report",
    attempt: 1,
    iteration: 0,
    signal: new AbortController().signal,
    db: { marker: "engine-owned" }
  };
  return withTaskRuntime(runtime, () => agent.generate({
    ultrafuzzTaskRuntime: runtime,
    taskContext: { runId: runtime.runId, nodeId: runtime.stepId, attempt: 1, iteration: 0 }
  }));
};
`,
      "utf8"
    );
    const linkPackage = (issuerRoot: string, name: string, target: string) => {
      const link = path.join(issuerRoot, "node_modules", ...name.split("/"));
      fs.mkdirSync(path.dirname(link), { recursive: true });
      fs.symlinkSync(path.relative(path.dirname(link), target), link);
    };
    linkPackage(root, "@smthrs/engine", engineRoot);
    linkPackage(root, "@smthrs/driver", driverRoot);
    linkPackage(engineRoot, "@smthrs/driver", driverRoot);

    const workflowPath = path.join(root, "workflow.mjs");
    fs.writeFileSync(
      workflowPath,
      `import { execute } from "@smthrs/engine";
import { getTaskRuntime } from "@smthrs/driver/task-runtime";
const observed = await execute({
  generate(args) {
    const explicitRuntime = args.ultrafuzzTaskRuntime;
    const forwarded = { ...args };
    Reflect.deleteProperty(forwarded, "ultrafuzzTaskRuntime");
    return {
      ambientVisible: getTaskRuntime() !== undefined,
      explicitMarker: explicitRuntime?.db?.marker,
      contextMatches:
        explicitRuntime?.runId === args.taskContext?.runId &&
        explicitRuntime?.stepId === args.taskContext?.nodeId,
      forwardedRuntime: Object.hasOwn(forwarded, "ultrafuzzTaskRuntime")
    };
  }
});
process.stdout.write(JSON.stringify(observed));
`,
      "utf8"
    );

    const probe = spawnSync(
      "bun",
      [
        `--config=${path.join(controls, "bunfig.toml")}`,
        `--env-file=${path.join(controls, "bun-empty.env")}`,
        "--no-env-file",
        "--no-install",
        "--no-addons",
        "--preserve-symlinks",
        "--preserve-symlinks-main",
        workflowPath
      ],
      { cwd: root, encoding: "utf8" }
    );
    assert.equal(probe.status, 0, probe.stderr);
    assert.deepEqual(JSON.parse(probe.stdout), {
      ambientVisible: false,
      explicitMarker: "engine-owned",
      contextMatches: true,
      forwardedRuntime: false
    });
  }
);

