testWhen(process.getuid?.() !== 0)(
  "a refresh that fails part way has already recorded every file it planned",
  async () => {
    const run = await launchPromptRefreshRun("prompt-refresh-partial", [
      { id: "node:project-discovery", state: "finished", attempt: 1 }
    ]);
    appendProjectPrompt(run.project, "setup/actors-flows.md", PROMPT_REFRESH_NOTE);
    const artifactDir = path.join(run.runRoot, "artifacts", "actors-flows");
    fs.chmodSync(artifactDir, 0o555);
    let diagnostics: Awaited<ReturnType<typeof run.resume>>;
    try {
      diagnostics = await run.resume();
    } finally {
      fs.chmodSync(artifactDir, 0o755);
    }

    const [incomplete, ...others] = diagnostics;
    assert.ok(incomplete?.code === "PROMPT_REFRESH_INCOMPLETE" && others.length === 0, JSON.stringify(diagnostics));
    assert.match(incomplete.message, /after 0 of 1 files: .*EACCES/u);
    assert.ok(incomplete.path);
    // refresh.json was published before the first file changed, so it lists the file the refresh
    // could not replace, which still holds its previous bytes.
    const { files } = JSON.parse(fs.readFileSync(path.join(run.runRoot, incomplete.path, "refresh.json"), "utf8")) as {
      files: Array<Record<string, unknown>>;
    };
    const sha256 = (text: string): string => crypto.createHash("sha256").update(text).digest("hex");
    const [planned, ...unplanned] = files;
    assert.ok(planned !== undefined && unplanned.length === 0, JSON.stringify(files));
    const { sha256: plannedSha256, ...plannedFile } = planned;
    assert.deepEqual(plannedFile, {
      path: "artifacts/actors-flows/prompt.rendered.md",
      attempt_id: "actors-flows",
      prompt: ".ultrafuzz/prompts/setup/actors-flows.md",
      previous_sha256: sha256(run.launchPrompts.actors)
    });
    assert.equal(run.prompt("actors-flows"), run.launchPrompts.actors);

    // Once the directory is writable again, the next resume applies the planned bytes.
    assert.deepEqual(
      (await run.resume()).map((diagnostic) => diagnostic.code),
      ["PROMPTS_REFRESHED"]
    );
    assert.ok(run.prompt("actors-flows").includes(PROMPT_REFRESH_NOTE));
    assert.equal(plannedSha256, sha256(run.prompt("actors-flows")));
  }
);

test("replay and fork restore a missing static prompt before they start an engine", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);
  const env = fakeSmithersEnv(project);
  // The fake runner names the replayed and forked runs after this run ID.
  const run = await startRun({ projectRoot: project, runId: "lifecycle-run", env });
  assert.equal(run.ok, true, JSON.stringify(run.diagnostics));
  assert.ok(run.value);
  const { run_id: runId, run_root: runRoot } = run.value;
  const plan = JSON.parse(fs.readFileSync(path.join(runRoot, "plan.json"), "utf8")) as {
    rendered_prompts: Array<{ rendered_prompt_path: string; rendered_prompt_snapshot_path: string }>;
  };
  const planned = plan.rendered_prompts[0];
  assert.ok(planned);
  const launchCopy = fs.readFileSync(path.join(runRoot, planned.rendered_prompt_snapshot_path));
  for (const [action, submit] of [
    ["replay", () => replayRun({ projectRoot: project, runId, env })],
    ["fork", () => forkRun({ projectRoot: project, runId, forkFrame: 44, env })]
  ] as const) {
    fs.rmSync(planned.rendered_prompt_path);
    const submitted = await submit();
    assert.equal(submitted.ok, true, `${action}: ${JSON.stringify(submitted.diagnostics)}`);
    assert.deepEqual(fs.readFileSync(planned.rendered_prompt_path), launchCopy, action);
  }
  // Any entry at the prompt path is left alone, a dangling symlink included: the workflow reads it
  // without following it and fails only that task, while publishing over it would refuse the command.
  fs.rmSync(planned.rendered_prompt_path);
  fs.symlinkSync(path.join(runRoot, "absent-prompt.md"), planned.rendered_prompt_path);
  const replayed = await replayRun({ projectRoot: project, runId, env });
  assert.equal(replayed.ok, true, JSON.stringify(replayed.diagnostics));
  assert.equal(fs.lstatSync(planned.rendered_prompt_path).isSymbolicLink(), true);
  assert.equal(fs.existsSync(path.join(runRoot, "absent-prompt.md")), false);
});

test("a static prompt that cannot be read no longer stops the whole workflow render", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);
  fs.symlinkSync(
    path.dirname(fs.realpathSync(path.join(process.cwd(), "node_modules", "smthrs"))),
    path.join(project, ".smithers", "node_modules"),
    "dir"
  );
  const plan = await planRun({ projectRoot: project, runId: "graph-missing-prompt", env: {} });
  assert.equal(plan.ok, true, JSON.stringify(plan.diagnostics));
  assert.ok(plan.value);
  const { compileSmithersWorkflow } = await import("../src/smithers.js");
  const compiled = compileSmithersWorkflow({
    projectRoot: project,
    config: plan.value.resolved_config,
    graph: plan.value.expanded_graph,
    runLayout: plan.value.layout,
    workflowName: "ultrafuzz-graph-missing-prompt",
    renderedPrompts: plan.value.rendered_prompts
  });
  // Every render builds the prompt of every available task. A file an agent or an operator deleted,
  // replaced, or made unreadable fails only its task when it prepares.
  const [broken] = plan.value.rendered_prompts;
  assert.ok(broken);
  const promptPath = broken.rendered_prompt_path;
  const outside = path.join(project, "outside-prompt.md");
  fs.writeFileSync(outside, "Text outside the run.\n", "utf8");
  const cases: Array<[string, () => void]> = [
    ["missing", () => undefined],
    ["directory", () => fs.mkdirSync(promptPath)],
    ["symlink", () => fs.symlinkSync(outside, promptPath)]
  ];
  if (process.getuid?.() !== 0) {
    cases.push([
      "unreadable",
      () => {
        fs.writeFileSync(promptPath, "An unreadable prompt.\n", "utf8");
        fs.chmodSync(promptPath, 0o000);
      }
    ]);
  }
  for (const [name, corrupt] of cases) {
    fs.rmSync(promptPath, { recursive: true, force: true });
    corrupt();
    const graphProcess = spawnSync(
      path.join(process.cwd(), "node_modules", ".bin", "smithers"),
      [
        "graph",
        compiled.evidenceWorkflowPath,
        "--run-id",
        compiled.smithersRunId,
        "--root",
        project,
        "--input",
        fs.readFileSync(compiled.inputPath, "utf8"),
        "--compact",
        "--format",
        "json"
      ],
      {
        cwd: project,
        encoding: "utf8",
        maxBuffer: 1024 * 1024 * 16,
        env: {
          ...process.env,
          OPENAI_API_KEY: "test-openai-api-key",
          ULTRAFUZZ_ARTIFACTS_MODULE: pathToFileURL(path.join(workspaceRoot(), "packages/artifacts/dist/index.js"))
            .href,
          ULTRAFUZZ_RUNTIME_MODULE: pathToFileURL(path.join(workspaceRoot(), "packages/runtime/dist/index.js")).href
        }
      }
    );
    assert.equal(graphProcess.status, 0, [name, graphProcess.stderr.trim(), graphProcess.stdout.trim()].join("\n"));
    const graph = JSON.parse(graphProcess.stdout) as { tasks?: Array<{ nodeId?: string }> };
    assert.equal(
      graph.tasks?.some((task) => task.nodeId === `prepare:${broken.attempt_id}`),
      true,
      name
    );
  }
});

test("compiled Smithers workflow passes a real non-executing graph smoke", async () => {
  const project = tempProject();
  initProject({ projectRoot: project, force: true });
  writeSmallTopology(project);
  fs.symlinkSync(
    path.dirname(fs.realpathSync(path.join(process.cwd(), "node_modules", "smthrs"))),
    path.join(project, ".smithers", "node_modules"),
    "dir"
  );

  const plan = await planRun({ projectRoot: project, runId: "graph-smoke", env: {} });
  assert.equal(plan.ok, true, JSON.stringify(plan.diagnostics));
  assert.ok(plan.value);
  const { compileSmithersWorkflow } = await import("../src/smithers.js");
  const compiled = compileSmithersWorkflow({
    projectRoot: project,
    config: plan.value.resolved_config,
    graph: plan.value.expanded_graph,
    runLayout: plan.value.layout,
    workflowName: "ultrafuzz-graph-smoke",
    renderedPrompts: plan.value.rendered_prompts,
    operatorPrompt: "graph smoke"
  });

  const graphProcess = spawnSync(
    path.join(process.cwd(), "node_modules", ".bin", "smithers"),
    [
      "graph",
      compiled.evidenceWorkflowPath,
      "--run-id",
      compiled.smithersRunId,
      "--root",
      project,
      "--input",
      fs.readFileSync(compiled.inputPath, "utf8"),
      "--compact",
      "--format",
      "json"
    ],
    {
      cwd: project,
      encoding: "utf8",
      maxBuffer: 1024 * 1024 * 16,
      env: {
        ...process.env,
        OPENAI_API_KEY: "test-openai-api-key",
        // No launch staged the sealed module copies the workflow imports by
        // default; render against this checkout's builds instead.
        ULTRAFUZZ_ARTIFACTS_MODULE: pathToFileURL(path.join(workspaceRoot(), "packages/artifacts/dist/index.js")).href,
        ULTRAFUZZ_RUNTIME_MODULE: pathToFileURL(path.join(workspaceRoot(), "packages/runtime/dist/index.js")).href
      }
    }
  );
  if (graphProcess.status !== 0 || graphProcess.stdout.trim() === "") {
    throw (
      graphProcess.error ??
      new Error(
        [`smithers graph exited ${String(graphProcess.status)}`, graphProcess.stderr.trim(), graphProcess.stdout.trim()]
          .filter(Boolean)
          .join("\n")
      )
    );
  }
  const graph = JSON.parse(graphProcess.stdout) as { tasks?: Array<{ nodeId?: string; retryPolicy?: unknown }> };
  assert.equal(graph.tasks?.[0]?.nodeId, "prepare:project-discovery");
  // Smithers receives the planned chain as the whole retry budget: a real wait
  // between attempts and no identical-failure stall verdict (#1084).
  assert.deepEqual(graph.tasks?.find((task) => task.nodeId === "node:project-discovery")?.retryPolicy, {
    backoff: "exponential",
    initialDelayMs: 60_000,
    maxIdenticalFailures: 0
  });
  assert.equal(
    graph.tasks?.some((task) => task.nodeId === "verify:project-discovery"),
    true
  );
});

function workspaceRoot(): string {
  let current = process.cwd();
  while (current !== path.dirname(current)) {
    if (fs.existsSync(path.join(current, "pnpm-workspace.yaml"))) {
      return current;
    }
    current = path.dirname(current);
  }
  return process.cwd();
}

for (const recovery of ["reset", "retry", "refresh"] as const) {
  test(`an unobserved failed occurrence stays in the attempt ledger across a stopped ${recovery}`, async () => {
    const project = tempProject();
    initProject({ projectRoot: project, force: true });
    writeSmallTopology(project, GENERIC_RUNTIME_MARKDOWN_PATH);
    const runId = `preserve-failed-${recovery}`;
    const workflowRunId = `ultrafuzz-${runId}`;
    const nodeId = "node:project-discovery";
    const events = [
      { type: "RunStarted" },
      { type: "NodeStarted", nodeId, attempt: 1 },
      { type: "NodeFailed", nodeId, attempt: 1, error: { message: "failed before observation" } }
    ];
    const env = fakeLifecycleSmithersEnv(project, {
      inspect: workflowInspect({
        workflowRunId,
        status: "failed",
        state: "failed",
        steps: [{ id: nodeId, state: "failed", attempt: 1 }]
      }),
      events: workflowEvents(workflowRunId, events)
    });
    const run = await startRun({ projectRoot: project, runId, env });
    assert.equal(run.ok, true, JSON.stringify(run.diagnostics));
    assert.ok(run.value);
    const ledgerPath = path.join(run.value.run_root, "attempts.jsonl");
    const sealPath = path.join(run.value.run_root, "smithers", "control-integrity.json");
    const seal = fs.readFileSync(sealPath);
    const resumed = await resumeRun({
      projectRoot: project,
      runId,
      env,
      ...(recovery === "retry" ? { retryFailed: true } : { resetNode: nodeId }),
      ...(recovery === "refresh" ? { refreshController: true } : {})
    });
    assert.equal(resumed.ok, true, JSON.stringify(resumed.diagnostics));
    assert.match(fs.readFileSync(fakeRunnerPath(env, "SMITHERS_FAKE_LOG"), "utf8"), /^timetravel /mu);
    assert.deepEqual(
      fs.readFileSync(sealPath),
      seal,
      "rendering a continuation must retain original control authority"
    );
    // The reset restarts numbering at attempt 1 and Smithers upserts that row, so
    // the failed occurrence survives only in the append-only event log.
    const activeEnv = fakeLifecycleSmithersEnv(project, {
      inspect: workflowInspect({
        workflowRunId,
        status: "running",
        state: "running",
        steps: [{ id: nodeId, state: "in-progress", attempt: 1 }]
      }),
      events: workflowEvents(workflowRunId, [
        ...events,
        { type: "RunStarted" },
        { type: "NodeStarted", nodeId, attempt: 1 }
      ])
    });
    const first = await syncRun({ projectRoot: project, runId, env: activeEnv });
    assert.equal(first.ok, true, JSON.stringify(first.diagnostics));
    assert.equal(first.value?.status, "running");
    const retained = fs.readFileSync(ledgerPath, "utf8");
    assert.deepEqual(
      retained
        .trim()
        .split("\n")
        .map((line) => {
          const entry = JSON.parse(line) as { source_event_sequence: number; outcome: string; failure_message: string };
          return [entry.source_event_sequence, entry.outcome, entry.failure_message];
        }),
      [[2, "failed", "failed before observation"]]
    );
    const second = await syncRun({ projectRoot: project, runId, env: activeEnv });
    assert.equal(second.ok, true, JSON.stringify(second.diagnostics));
    assert.equal(fs.readFileSync(ledgerPath, "utf8"), retained);
  });
}

